(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("philo-on-mating-e", [{"sp": "HDR", "t": "Περὶ τῆς πρὸς τὰ προπαιδεύματα συνόδου"}, {"sp": "N", "t": "“Σάρα δὲ ἡ γυνὴ Ἀβραὰμ οὐκ ἔτικτεν αὐτῷ. ἦν δὲ αὐτῇ παιδίσκη Αἰγυπτία, ᾗ ὄνομα Ἄγαρ. εἶπε δὲ Σάρα πρὸς Ἀβραάμ· ἰδού, συνέκλεισέ με κύριος τοῦ μὴ τίκτειν, εἴσελθε πρὸς τὴν παιδίσκην μου, ἵνα τεκνοποιήσῃς ἐξ αὐτῆς”.", "st": "1"}, {"sp": "N", "t": "τὸ Σάρας ὄνομα μεταληφθέν ἐστιν “ἀρχή μου”· φρόνησις δὲ ἡ ἐν ἐμοὶ καὶ σωφροσύνη ἡ ἐν ἐμοὶ καὶ ἡ ἐπὶ μέρους δικαιοσύνη καὶ ἑκάστη τῶν ἄλλων ἀρετῶν, ἣν περὶ ἐμὲ μόνον εἶναι συμβέβηκεν, ἀρχή ἐστιν ἐμοῦ μόνου· ἐπιστατεῖ γάρ μου καὶ ἡγεμονεύει πειθαρχεῖν ἐγνωκότος, βασιλὶς ἐκ φύσεως ὑπάρχουσα.", "st": "2"}, {"sp": "N", "t": "ταύτην Μωυσῆς, τὸ παραδοξότατον, καὶ στεῖραν ἀποφαίνει καὶ πολυγονωτάτην, εἴ γε τὸ πολυανθρωπότατον τῶν ἐθνῶν ἐξ αὐτῆς ὁμολογεῖ γενέσθαι. τῷ γὰρ ὄντι ἡ ἀρετὴ πρὸς μὲν τὰ φαῦλα πάντα ἐστείρωται, τῶν δὲ ἀγαθῶν εὐτοκίᾳ χρῆται τοιαύτῃ, ὡς μηδὲ μαιευτικῆς τέχνης — φθάνει γὰρ ἀποτίκτουσα — δεῖσθαι.", "st": "3"}, {"sp": "N", "t": "τὰ μὲν οὖν ζῷα καὶ φυτὰ διαλείποντα τὸν πλείω χρόνον ἅπαξ ἢ δὶς τὸ πλεῖστον τοὺς οἰκείους δι’ ἐνιαυτοῦ φέρει καρπούς, καθ’ ὃν ἔταξεν ἀριθμὸν ἑκάστοις ἡ φύσις ἐναρμοζόμενον ταῖς ἐτησίοις ὥραις· ἀρετὴ δὲ οὐ διαλείπουσα ἀνελλιπῶς δὲ καὶ ἀδιαστάτως κατὰ τοὺς ἀμερεῖς χρόνους ἀεὶ γεννᾷ, βρέφη μὲν οὐδαμῶς, λόγους δὲ ἀστείους καὶ βουλὰς ἀνεπιλήπτους καὶ ἐπαινετὰς πράξεις.", "st": "4"}, {"sp": "N", "t": "ἀλλ’ οὔτε πλοῦτος, ᾧ μὴ δυνατόν ἐστι χρῆσθαι, τοὺς κεκτημένους ὠφελεῖ οὔτε ἡ φρονήσεως εὐτοκία, ἐὰν μὴ καὶ ἡμῖν αὐτοῖς τὰ ὠφέλιμα τίκτῃ. τοὺς μὲν γὰρ εἰσάπαν ἀξίους ἔκρινε τῆς συμβιώσεως αὐτῆς, οἱ δ’ οὔπω τὴν ἡλικίαν ἔδοξαν ἔχειν, ὡς ἐπαινετῆς καὶ σώφρονος οἰκουρίας ἀνέχεσθαι· οἷς τὰ προτέλεια τῶν γάμων ἐφῆκε ποιεῖσθαι, ἐλπίδα καὶ τοῦ θύσειν τοὺς γάμους παρασχοῦσα.", "st": "5"}, {"sp": "N", "t": "Σάρα οὖν, ἡ ἄρχουσά μου τῆς ψυχῆς ἀρετή, ἔτικτε μέν, ἐμοὶ δ’ οὐκ ἔτικτε· οὐ γὰρ ἠδυνάμην πω νέος ὢν τὰ γεννήματα αὐτῆς παραδέχεσθαι, τὸ φρονεῖν, τὸ δικαιοπραγεῖν, τὸ εὐσεβεῖν, διὰ τὸ πλῆθος τῶν νόθων παίδων, οὓς ἀπεκύησάν μοι αἱ κεναὶ δόξαι. τροφαὶ γὰρ αἱ τούτων καὶ συνεχεῖς ἐπιμέλειαι καὶ φροντίδες ἄληκτοι τῶν γνησίων καὶ ὡς ἀληθῶς ἀστῶν ὀλιγωρεῖν ἠνάγκασαν.", "st": "6"}, {"sp": "N", "t": "καλὸν οὖν εὔχεσθαι τὴν ἀρετὴν μὴ μόνον τίκτειν, ἣ καὶ δίχα εὐχῆς εὐτοκεῖ, ἀλλὰ καὶ ἡμῖν αὐτοῖς τίκτειν, ἵνα τῶν σπερμάτων καὶ γεννημάτων αὐτῆς μεταλαγχάνοντες εὐδαιμονῶμεν. εἴωθε γὰρ θεῷ μόνῳ τίκτειν, τὰς ἀπαρχὰς ὧν ἔτυχεν ἀγαθῶν εὐχαρίστως ἀποδιδοῦσα τῷ τὴν ἀειπάρθενον μήτραν, ὥς φησι Μωυσῆς, ἀνοίξαντι.", "st": "7"}, {"sp": "N", "t": "καὶ γὰρ τὴν λυχνίαν, τὸ ἀρχέτυπον τοῦ μιμήματος παράδειγμα, ἐκ τοῦ ἑνὸς μέρους φησὶ φαίνειν, δηλονότι τοῦ πρὸς θεόν· ἑβδόμη γὰρ οὖσα καὶ μέση τῶν ἓξ καλαμίσκων δίχα διῃρημένων εἰς τριάδας, ἑκατέρωθεν δορυφορούντων, ἄνω τὰς αὐγὰς ἀποστέλλει πρὸς τὸ ὄν, λαμπρότερον ἡγουμένη τὸ φέγγος ἢ ὡς δύνασθαι", "st": "8"}, {"sp": "N", "t": "θνητὴν αὐτῷ προσβάλλειν ὄψιν. διὰ τοῦτο οὔ φησι μὴ τίκτειν τὴν Σάραν, ἀλλ’ αὐτῷ τινι μὴ τίκτειν. οὐ γάρ ἐσμεν ἱκανοὶ δέξασθαί πω γονὰς ἀρετῆς, εἰ μὴ πρότερον ἐντύχοιμεν αὐτῆς τῇ θεραπαινίδι· θεραπαινὶς δὲ σοφίας ἡ διὰ τῶν προπαιδευμάτων ἐγκύκλιος μουσική.", "st": "9"}, {"sp": "N", "t": "ὥσπερ γὰρ ἐν μὲν οἰκίαις αὔλειοι πρόκεινται κλισιάδων, ἐν δὲ πόλεσι τὰ προάστεια, δι’ ὧν εἴσω βαδίζειν ἔνεστιν, οὕτως καὶ ἀρετῆς πρόκειται τὰ ἐγκύκλια· ταῦτα γὰρ ὁδός ἐστιν ἐπ’ ἐκείνην φέρουσα.", "st": "10"}, {"sp": "N", "t": "Χρὴ δ’ εἰδέναι, ὅτι τῶν μεγάλων ὑποθέσεων μεγάλα καὶ τὰ προοίμια εἶναι συμβέβηκε. μεγίστη δὲ ὑπόθεσις ἀρετή· καὶ γὰρ περὶ μεγίστην ὕλην καταγίνεται, τὸν σύμπαντα ἀνθρώπων βίον. εἰκότως οὖν οὐ βραχέσι χρήσεται προοιμίοις, ἀλλὰ γραμματικῇ, γεωμετρίᾳ, ἀστρονομία, ῥητορικῇ, μουσικῇ, τῇ ἄλλῃ λογικῇ θεωρίᾳ πάσῃ, ὧν ἐστι σύμβολον ἡ Σάρας θεραπαινὶς Ἄγαρ, ὡς ἐπιδείξομεν.", "st": "11"}, {"sp": "N", "t": "“εἶπε” γάρ φησι “Σάρα πρὸς Ἀβραάμ· ἰδοὺ συνέκλεισέ με κύριος τοῦ μὴ τίκτειν· εἴσελθε πρὸς τὴν παιδίσκην μου, ἵνα τεκνοποιήσῃς ἐξ αὐτῆς”. τὰς σωμάτων πρὸς σώματα μίξεις καὶ ὁμιλίας ἡδονὴν ἐχούσας τὸ τέλος ὑπεξαιρετέον τοῦ παρόντος λόγου· νοῦ γὰρ πρὸς ἀρετήν ἐστι σύνοδος ἐξ αὐτῆς ἐφιεμένου παιδοποιεῖσθαι, εἰ δὲ μὴ δύναιτο εὐθύς, ἀλλά τοι τὴν θεραπαινίθα αὐτῆς,", "st": "12"}, {"sp": "N", "t": "τὴν μέσην παιδείαν, ἐγγυᾶσθαι διδασκομένου. ἄξιον δὲ τῆς αἰδοῦς καταπλαγῆναι σοφίαν, ἥτις τὸ βραδὺ πρὸς γένεσιν ἢ τελέως ἄγονον οὐκ ἠξίωσεν ἡμῖν ὀνειδίσαι, καίτοι τοῦ χρησμοῦ τἀληθὲς εἰπόντος, ὅτι “οὐκ ἔτικτεν,” οὐ διὰ φθόνον, ἀλλὰ διὰ τὴν ἡμῶν αὐτῶν ἀνεπιτηδειότητα· “συνέκλεισε” γάρ φησι “μὲ κύριος τοῦ μὴ τίκτειν”, καὶ οὐκέτι προστίθησιν “ὑμῖν”, ἵνα μὴ προφέρειν ἀτυχίαν καὶ ὀνειδίζειν ἑτέροις δοκῇ.", "st": "13"}, {"sp": "N", "t": "“εἴσελθε” οὖν φησι “πρὸς τὴν παιδίσκην μου,” τὴν τῶν μέσων καὶ ἐγκυκλίων ἐπιστημῶν μέσην παιδείαν, “ἵνα τεκνοποιήσῃ πρότερον ἐξ αὐτῆς”· αὖθις γὰρ δυνήσῃ καὶ τῶν πρὸς τὴν δέσποιναν ὁμιλιῶν ἐπὶ γενέσει παίδων γνησίων ἀπόνασθαι.", "st": "14"}, {"sp": "N", "t": "γραμματικὴ μὲν γὰρ ἱστορίαν τὴν παρὰ ποιηταῖς καὶ συγγραφεῦσιν ἀναδιδάξασα νόησιν καὶ πολυμάθειαν ἐργάσεται καὶ καταφρονητικῶς ἔχειν ἀναδιδάξει τῶν ὅσα αἱ κεναὶ δόξαι τυφοπλαστοῦσι, διὰ τὰς κακοπραγίας, αἷς τοὺς ᾀδομένους παρ’ αὐτοῖς ἥρωάς τε καὶ ἡμιθέους λόγος ἔχει χρήσασθαι.", "st": "15"}, {"sp": "N", "t": "μουσικὴ δὲ τὸ μὲν ἄρρυθμον [ἐν] ῥυθμοῖς, τὸ δ’ ἀνάρμοστον ἁρμονίᾳ, τὸ δ’ ἀπῳδὸν καὶ ἐκμελὲς μέλει κατεπᾴδουσα τὸ ἀσύμφωνον εἰς συμφωνίαν ἄξει. γεωμετρία δ’ ἰσότητος καὶ ἀναλογίας ἐμβαλλομένη τὰ σπέρματα εἰς ψυχὴν φιλομαθῆ γλαφυρότητι συνεχοῦς θεωρίας δικαιοσύνης ζῆλον ἐμποιήσει.", "st": "16"}, {"sp": "N", "t": "ῥητορικὴ δὲ καὶ τὸν νοῦν πρὸς θεωρίαν ἀκονησαμένη καὶ πρὸς ἑρμηνείαν γυμνάσασα τὸν λόγον καὶ συγκροτήσασα λογικὸν ὄντως ἀποδείξει τὸν ἄνθρωπον ἐπιμεληθεῖσα τοῦ ἰδίου καὶ ἐξαιρέτου, ὃ μηδενὶ τῶν ἄλλων ζῴων ἡ φύσις δεδώρηται.", "st": "17"}, {"sp": "N", "t": "διαλεκτικὴ δὲ ἡ ῥητορικῆς ἀδελφὴ καὶ δίδυμος, ὡς εἶπόν τινες, τοὺς ἀληθεῖς τῶν ψευδῶν λόγους διακρίνουσα καὶ τὰς τῶν σοφισμάτων πιθανότητας ἐλέγχουσα μεγάλην νόσον ψυχῆς, ἀπάτην, ἀκέσεται. τούτοις οὖν καὶ τοῖς παραπλησίοις ἐνομιλῆσαι καὶ ἐμπρομελετῆσαι λυσιτελές· ἴσως γάρ, ἴσως, ὃ πολλοῖς συνέβη, διὰ τῶν ὑπηκόων ταῖς βασιλίσιν ἀρεταῖς γνωρισθησόμεθα.", "st": "18"}, {"sp": "N", "t": "οὐχ ὁρᾷς, ὅτι καὶ τὸ σῶμα ἡμῶν οὐ πρότερον πεπηγυίαις καὶ πολυτελέσι χρῆται τροφαῖς, πρὶν ἢ ταῖς ἀποικίλοις καὶ γαλακτώδεσιν ἐν ἡλικίᾳ τῇ βρεφώδει; τὸν αὐτὸν δὴ τρόπον καὶ τῇ ψυχῇ παιδικὰς μὲν νόμισον εὐτρεπίσθαι τροφὰς τὰ ἐγκύκλια καὶ τὰ καθ’ ἕκαστον αὐτῶν θεωρήματα, τελειοτέρας δὲ καὶ πρεπούσας ἀνδράσιν ὡς ἀληθῶς τὰς ἀρετάς.", "st": "19"}, {"sp": "N", "t": "Οἱ δὲ πρῶτοι τῆς μέσης παιδείας χαρακτῆρες διὰ δυεῖν παρίστανται συμβόλων, τοῦ τε γένους καὶ τοῦ ὀνόματος. γένος μέν ἐστιν Αἰγυπτία, καλεῖται δὲ Ἄγαρ, τοῦτο δὲ ἑρμηνευθέν ἐστι παροίκησις· ἀνάγκη γὰρ τὸν ἐγχορεύοντα ταῖς ἐγκυκλίοις θεωρίαις καὶ πολυμαθείας ἑταῖρον ὄντα τῷ γεώδει καὶ Αἰγυπτίῳ προσκεκληρῶσθαι σώματι, χρῄζοντα καὶ ὀφθαλμῶν, ὡς ἰδεῖν καὶ ἀναγνῶναι, καὶ ὤτων, ὡς προσσχεῖν τε καὶ ἀκοῦσαι, καὶ τῶν ἄλλων αἰσθήσεων, ὡς ἕκαστον τῶν αἰσθητῶν ἀναπτύξαι.", "st": "20"}, {"sp": "N", "t": "δίχα γὰρ τοῦ κρίνοντος τὸ κρινόμενον οὐ πέφυκε καταλαμβάνεσθαι· κρίνει δὲ τὸ αἰσθητὸν αἴσθησις, ὥστ’ ἀκριβωθῆναί τι τῶν κατὰ τὸν αἰσθητὸν κόσμον, ἐν οἷς ἡ πλείων μοῖρα τοῦ φιλοσοφεῖν, οὐκ ἐνῆν ἄνευ αἰσθήσεως. αἴσθησις δέ, τὸ σωματοειδέστερον ψυχῆς μέρος, τῷ τῆς ὅλης ψυχῆς ἀγγείῳ προσερρίζωται, τὸ δὲ τῆς ψυχῆς ἀγγεῖον Αἴγυπτος διὰ συμβόλου προσονομάζεται.", "st": "21"}, {"sp": "N", "t": "χαρακτὴρ μὲν εἷς ὁ ἀπὸ τοῦ γένους οὗτος, ὃν ἡ θεραπαινὶς ἀρετῆς ἔλαχεν· ὁ δὲ ἀπὸ τοῦ ὀνόματος ποῖός ἐστιν, ἐπισκεψώμεθα. τὴν μέσην παιδείαν παροίκου λόγον ἔχειν συμβέβηκεν· ἐπιστήμη μὲν γὰρ καὶ σοφία καὶ ἀρετὴ πᾶσα αὐθιγενὴς καὶ αὐτόχθων καὶ πολῖτις ὡς ἀληθῶς ἐστι μόνη τοῦ παντός, αἱ δὲ ἄλλαι παιδεῖαι δευτέρων καὶ τρίτων καὶ ὑστάτων ἄθλων τυγχάνουσαι μεθόριοι ξένων καὶ ἀστῶν εἰσιν· οὐδετέρου τε γὰρ γένους ἀκράτου καὶ πάλιν ἀμφοῖν κατά τινα κοινωνίαν ἐφάπτονται.", "st": "22"}, {"sp": "N", "t": "πάροικος γὰρ τῷ μὲν ἐνδιατρίβειν ἀστοῖς, τῷ δὲ μὴ κατοικεῖν ἀλλοδαποῖς ἰσοῦται· καθάπερ, οἶμαι, καὶ οἱ θετοὶ παῖδες, ᾗ μὲν κληρονομοῦσι τὰ τῶν θεμένων, τοῖς γνησίοις, ᾗ δ’ οὐ γεγέννηνται πρὸς αὐτῶν, τοῖς ὀθνείοις. ὃν δὴ λόγον ἔχει δέσποινα μὲν πρὸς θεραπαινίδα, γυνὴ δὲ ἀστὴ πρὸς παλλακήν, τοῦτον ἕξει τὸν λόγον ἀρετὴ Σάρρα πρὸς παιδείαν Ἄγαρ· ὥστ’ εἰκότως τοῦ θεωρίαν καὶ ἐπιστήμην ἐζηλωκότος, Ἀβραὰμ ὄνομα, γένοιτ’ ἂν ἡ μὲν ἀρετή, Σάρρα, γυνή, παλλακὴ δὲ Ἄγαρ, ἡ ἐγκύκλιος μουσικὴ πᾶσα.", "st": "23"}, {"sp": "N", "t": "ᾧτινι μὲν οὖν φρόνησις ἐκ διδασκαλίας περιγίνεται, τὴν Ἄγαρ οὐκ ἂν ἀποδοκιμάζοι· πάνυ γὰρ ἀναγκαία ἡ τῶν προπαιδευμάτων κτῆσις. εἰ δέ τις τοὺς ὑπὲρ ἀρετῆς ἄθλους ἐγνωκὼς διαπονεῖν μελέταις χρῆται συνεχέσιν ἀνενδότως ἔχων πρὸς ἄσκησιν, δύο μὲν ἀστάς, παλλακὰς δὲ τὰς ἴσας, τῶν ἀστῶν θεραπαινίδας, ἄξεται.", "st": "24"}, {"sp": "N", "t": "φύσιν δὲ καὶ ἰδέαν ἔλαχεν αὐτῶν ἑκάστη διάφορον. αὐτίκα τῶν ἀστῶν ἡ μέν ἐστιν ὑγιεινοτάτη καὶ εὐσταθεστάτη καὶ εἰρηνικωτάτη κίνησις, ἣν ἀπὸ τοῦ συμβεβηκότος ὠνόμασε Λείαν. ἡ δὲ ἔοικεν ἀκόνῃ, καλεῖται δὲ Ῥαχήλ, πρὸς ἣν ὁ φίλαθλος καὶ φιλογυμναστὴς νοῦς παραθηγόμενος ὀξύνεται· ἑρμηνεύεται δὲ ὅρασις βεβηλώσεως, οὐκ ἐπειδὴ βεβήλως ὁρᾷ, ἀλλὰ τοὐναντίον, ὅτι τὰ ὁρατὰ καὶ αἰσθητὰ παρὰ τὴν ἀκήρατον φύσιν τῶν ἀοράτων καὶ νοητῶν οὐκ εὐαγῆ βέβηλα δὲ εἶναι νομίζει.", "st": "25"}, {"sp": "N", "t": "τῆς γὰρ ψυχῆς ἡμῶν διμεροῦς ὑπαρχούσης καὶ τὸ μὲν λογικὸν τὸ δὲ ἄλογον ἐχούσης, ἀρετὴν ἑκατέρῳ ὑπάρχειν συμβέβηκε, Λείαν μὲν τῷ λογικῷ, τῷ δὲ ἀλόγῳ Ῥαχήλ.", "st": "26"}, {"sp": "N", "t": "γυμνάζει γὰρ ἡμᾶς ἡ μὲν διὰ τῶν αἰσθήσεων καὶ τῶν τοῦ ἀλόγου μερῶν πάντων καταφρονητικῶς ἔχειν ὧν ἀλογεῖν ἄξιον, δόξης καὶ πλούτου καὶ ἡδονῆς, ἃ περίβλεπτα καὶ περιμάχητα ὁ πολὺς καὶ ἀγελαῖος ἀνθρώπων ὄχλος κρίνει δεδεκασμέναις μὲν ἀκοαῖς, δεδεκασμένῳ δὲ καὶ τῷ ἄλλῳ τῶν αἰσθήσεων δικαστηρίῳ·", "st": "27"}, {"sp": "N", "t": "ἡ δὲ ἀναδιδάσκει τὴν ἀνώμαλον καὶ τραχεῖαν ὁδὸν ἄβατον φιλαρέτοις ψυχαῖς ἐκτρέπεσθαι, λείως δὲ διὰ τῆς λεωφόρου βαίνειν ἄνευ πταισμάτων καὶ τῶν ἐν ποσὶν ὀλίσθων.", "st": "28"}, {"sp": "N", "t": "ἀναγκαίως οὖν τῆς μὲν προτέρας ἔσται θεραπαινὶς ἡ διὰ τῶν φωνητηρίων ὀργάνων ἑρμηνευτικὴ δύναμις καὶ ἡ λογικὴ σοφισμάτων εὕρεσις εὐστόχῳ πιθανότητι καταγοητεύουσα, τῆς δὲ ἀναγκαῖαι τροφαί, πόσις τε καὶ βρῶσις.", "st": "29"}, {"sp": "N", "t": "ὀνόματα δὲ ἡμῖν τῶν δυεῖν θεραπαινίδων ἀνέγραψε, Ζέλφαν τε καὶ Βάλλαν. ἡ μὲν οὖν Ζέλφα μεταληφθεῖσα πορευόμενον καλεῖται στόμα, τῆς ἑρμηνευτικῆς καὶ διεξοδικῆς σύμβολον δυνάμεως, ἡ δὲ Βάλλα κατάποσις, τὸ πρῶτον καὶ ἀναγκαιότατον θνητῶν ζῴων ἔρεισμα· καταπόσει γὰρ τὰ σώματα ἡμῶν ἐνορμεῖ, καὶ τὰ τοῦ ζῆν πείσματα ἐκ ταύτης ὡς ἀπὸ κρηπῖδος ἐξῆπται.", "st": "30"}, {"sp": "N", "t": "πάσαις οὖν ταῖς εἰρημέναις δυνάμεσιν ὁ ἀσκητὴς ἐνομιλεῖ, ταῖς μὲν ὡς ἐλευθέραις καὶ ἀσταῖς, ταῖς δὲ ὡς δούλαις καὶ παλλακίσιν. ἐφίεται μὲν γὰρ τῆς Λείας κινήσεως — λεία δὲ κίνησις ἐν μὲν σώματι γινομένη ὑγείαν, ἐν δὲ ψυχῇ καλοκἀγαθίαν καὶ δικαιοσύνην ἂν ἐργάσαιτο —, Ῥαχὴλ δὲ ἀγαπᾷ πρὸς τὰ πάθη παλαίων καὶ πρὸς ἐγκράτειαν ἀλειφόμενος καὶ τοῖς αἰσθητοῖς πᾶσιν ἀντιταττόμενος.", "st": "31"}, {"sp": "N", "t": "διττοὶ μὲν γὰρ ὠφελείας τρόποι, ἢ κατὰ ἀπόλαυσιν ἀγαθῶν ὡς ἐν εἰρήνῃ ἢ κατὰ ἀντίταξιν καὶ ὑφαίρεσιν κακῶν ὡς ἐν πολέμῳ. Λεία μὲν οὖν ἐστι, καθ’ ἣν συμβαίνει τὰ πρεσβύτερα καὶ ἡγεμονεύοντα ἀγαθὰ καρποῦσθαι, Ῥαχὴλ δέ, καθ’ ἣν τὰ ὡς ἂν ἐκ πολέμου λάφυρα. τοιαύτη μὲν ἡ πρὸς τὰς ἀστὰς συμβίωσις.", "st": "32"}, {"sp": "N", "t": "χρῄζει δὲ ὁ ἀσκητὴς Βάλλας μέν, καταπόσεως, ἀλλὰ ὡς δούλης καὶ παλλακίδος — ἄνευ γὰρ τροφῆς καὶ ζωῆς οὐδ’ ἂν τὸ εὖ ζῆν περιγένοιτο, ἐπειδὴ τὰ μέσα τῶν ἀμεινόνων ἀεὶ θεμέλιοι —, χρῄζει δὲ καὶ Ζέλφας, διεξοδικῆς ἑρμηνείας, ἵνα τὸ λογικὸν αὐτῷ διχόθεν συνερανίζηται πρὸς τελείωσιν, ἔκ τε τῆς κατὰ διάνοιαν πηγῆς καὶ ἐκ τῆς περὶ τὸ φωνητήριον ὄργανον ἀπορροῆς.", "st": "33"}, {"sp": "N", "t": "ἀλλ’ οὗτοι μὲν καὶ πλειόνων γυναικῶν καὶ παλλακίδων, οὐκ ἀστῶν μόνον, ἄνδρες ἐγένοντο, ὡς αἱ ἱεραὶ μηνύουσι γραφαί· τῷ δὲ Ἰσαὰκ οὔτε πλείους γυναῖκες οὔτε συνόλως παλλακή, μόνη δ’ ἡ κουρίδιος ἄχρι παντὸς συνοικεῖ. διὰ τί;", "st": "34"}, {"sp": "N", "t": "ὅτι καὶ ἡ διδακτικὴ ἀρετή, ἣν Ἀβραὰμ μέτεισι, πλειόνων δεῖται, γνησίων μὲν τῶν κατὰ φρόνησιν, νόθων δὲ τῶν κατὰ τὰ ἐγκύκλια προπαιδεύματα θεωρημάτων, καὶ ἡ δι’ ἀσκήσεως τελειουμένη, περὶ ἣν Ἰακὼβ ἐσπουδακέναι φαίνεται· διὰ πλειόνων γὰρ καὶ διαφερόντων αἱ ἀσκήσεις δογμάτων, ἡγουμένων ἑπομένων, προαπαντώντων ὑστεριζόντων, πόνους τοτὲ μὲν ἐλάττους τοτὲ δὲ μείζους ἐχόντων.", "st": "35"}, {"sp": "N", "t": "τὸ δὲ αὐτομαθὲς γένος, οὗ κεκοινώνηκεν Ἰσαάκ, ἡ εὐπαθειῶν ἀρίστη χαρά, φύσεως ἁπλῆς καὶ ἀμιγοῦς καὶ ἀκράτου μεμοίραται, μήτε ἀσκήσεως μήτε διδασκαλίας δεόμενον, ἐν οἷς παλλακίδων ἐπιστημῶν, οὐκ ἀστῶν μόνον, ἐστὶ χρεία. θεοῦ γὰρ τὸ αὐτομαθὲς καὶ αὐτοδίδακτον ἄνωθεν ἀπ’ οὐρανοῦ καλὸν ὀμβρήσαντος ἀμήχανον ἦν ἔτι δούλαις καὶ παλλακαῖς συμβιῶναι τέχναις, νόθων δογμάτων οἷα παίδων ὀρεχθέντα.", "st": "36"}, {"sp": "N", "t": "δεσποίνης γὰρ καὶ βασιλίδος ἀρετῆς ὁ τούτου λαχὼν τοῦ γέρως ἀνὴρ ἀναγράφεται· καλεῖται δὲ παρὰ μὲν Ἕλλησιν ὑπομονή, παρὰ δὲ Ἑβραίοις Ῥεβέκκα. ζητεῖ γὰρ ὁ ἄπονον καὶ ἀταλαίπωρον εὑράμενος σοφίαν δι’ εὐμοιρίαν φύσεως καὶ εὐτοκίαν ψυχῆς οὐδὲν τῶν εἰς βελτίωσιν.", "st": "37"}, {"sp": "N", "t": "ἔχει γὰρ ἐν ἑτοίμῳ τέλεια τὰ τοῦ θεοῦ δῶρα χάρισι ταῖς πρεσβυτέραις ἐπιπνευσθέντα, βούλεται δὲ καὶ εὔχεται ταῦτα ἐπιμεῖναι. παρό μοι δοκεῖ καὶ ὁ εὐεργέτης, ἵνα διαιωνίζωσιν αἱ χάριτες αὐτοῦ τῷ λαβόντι, γυναῖκα τὴν ἐπιμονὴν ἐγγυῆσαι.", "st": "38"}, {"sp": "N", "t": "Ἀνάμνησίς γε μὴν μνήμης τὰ δευτερεῖα φέρεται καὶ ὁ ἀναμιμνῃσκόμενος τοῦ μεμνημένου· ὁ μὲν γὰρ ἔοικε τῷ συνεχῶς ὑγιαίνοντι, ὁ δὲ τῷ ἐκ νόσου ἀναλαμβάνοντι· λήθη γὰρ νόσος μνήμης.", "st": "39"}, {"sp": "N", "t": "ἀνάγκη δὲ τὸν ὑπομνήσει χρώμενον ἐκλαθέσθαι πρότερον ὧν ἐμέμνητο. τὴν μὲν οὖν μνήμην Ἐφραΐμ, ἑρμηνευόμενον καρποφορίαν, ὁ ἱερὸς ὀνομάζει λόγος, τὴν δὲ ἀνάμνησιν ἐκ λήθης Μανασσῆν προσαγορεύουσιν Ἑβραῖοι.", "st": "40"}, {"sp": "N", "t": "ὄντως γὰρ ἡ μὲν τοῦ μεμνημένου ψυχὴ καρποφορεῖ ἃ ἔμαθεν οὐδὲν ἀποβάλλουσα αὐτῶν, ἡ δὲ τοῦ ἀναμνήσει χρωμένου ἔξω λήθης γίνεται, ᾗ πρὶν ὑπομνησθῆναι κατέσχητο. μνημονικῷ μὲν οὖν ἀνδρὶ ἀστὴ συμβιοῖ γυνή, μνήμη, ἐπιλανθανομένῳ δὲ παλλακίς, ἀνάμνησις, Σύρα τὸ γένος, ἀλαζὼν καὶ ὑπέραυχος· Συρία γὰρ ἑρμηνεύεται μετέωρα.", "st": "41"}, {"sp": "N", "t": "τῆς δὲ παλλακίδος ταύτης, ἀναμνήσεως, υἱός ἐστι Μαχείρ, ὡς Ἑβραῖοι καλοῦσιν, ὡς δὲ Ἕλληνες, πατρός· νομίζουσι γὰρ οἱ ἀναμιμνῃσκόμενοι τὸν πατέρα νοῦν αἴτιον εἶναι τοῦ ὑπομνησθῆναι, καὶ οὐ λογίζονται, ὅτι ὁ αὐτὸς οὗτος ἐχώρησέ ποτε καὶ λήθην, οὐκ ἂν δεξάμενος αὐτήν, εἰ παρ’ αὐτὸν ἦν τὸ μεμνῆσθαι.", "st": "42"}, {"sp": "N", "t": "λέγεται γάρ· “ἐγένοντο υἱοὶ Μανασσῆ, οὓς ἔτεκεν αὐτῷ ἡ παλλακὴ ἡ Σύρα, τὸν Μαχείρ· Μαχεὶρ δὲ ἐγέννησε τὸν Γαλαάδ”.", "st": "43"}, {"sp": "N", "t": "καὶ Ναχὼρ μέντοι, ὁ ἀδελφὸς Ἀβραάμ, ἔχει δύο γυναῖκας, ἀστήν τε καὶ παλλακήν· ὄνομα δὲ τῆς μὲν ἀστῆς Μελχά, Ῥουμὰ δὲ τῆς παλλακίδος. ἀλλ’ οὐχ ἱστορικὴ γενεαλογία ταῦτ’ ἐστὶν ἀναγραφεῖσα παρὰ τῷ σοφῷ νομοθέτῃ — μηδεὶς τοῦτ’ εὖ φρονῶν ὑπονοήσειεν —, ἀλλὰ πραγμάτων ψυχὴν ὠφελῆσαι δυναμένων διὰ συμβόλων ἀνάπτυξις. τὰ δ’ ὀνόματα μεταβαλόντες εἰς τὴν ἡμετέραν διάλεκτον εἰσόμεθα τὴν ὑπόσχεσιν ἀληθῆ. Φέρ’ οὖν ἕκαστον αὐτῶν ἐρευνήσωμεν.", "st": "44"}, {"sp": "N", "t": "Ναχὼρ ἑρμηνεύεται φωτὸς ἀνάπαυσις, Μελχὰ δὲ βασίλισσα, Ῥουμὰ δὲ ὁρῶσά τι. τὸ μὲν οὖν φῶς ἔχειν κατὰ διάνοιαν ἀγαθόν, τὸ δὲ ἀναπαυόμενον καὶ ἠρεμοῦν καὶ ἀκίνητον οὐ τέλειον ἀγαθόν· ἡσυχίᾳ μὲν γὰρ τὰ κακὰ χρῆσθαι λυσιτελές, τὰ δὲ ἀγαθὰ κινήσει συμφέρον.", "st": "45"}, {"sp": "N", "t": "τίς γὰρ ὄνησις εὐφώνου ἡσυχάζοντος ἢ μὴ αὐλοῦντος αὐλητοῦ ἢ κιθαριστοῦ μὴ κιθαρίζοντος ἢ συνόλως τεχνίτου τὰ κατὰ τὴν τέχνην μὴ ἐνεργοῦντος; ἡ γὰρ ἄνευ πράξεως θεωρία ψιλὴ πρὸς οὐδὲν ὄφελος τοῖς ἐπιστήμοσιν· οὐ γὰρ ὁ παγκρατιάζειν ἢ πυκτεύειν ἢ παλαίειν εἰδὼς ἐξαγκωνισθεὶς ἀπόναιτ’ ἂν ἀθλήσεως ἢ ὁ τὴν τοῦ τρέχειν ἐπιστήμην ἐκμαθών, εἰ ποδαγρικῷ χρήσαιτο πάθει ἤ τινα ἄλλην περὶ τὰς βάσεις κῆρα ἀναδέξαιτο.", "st": "46"}, {"sp": "N", "t": "φῶς δὲ ψυχῆς ἡλιοειδέστατον ἐπιστήμη· καθάπερ γὰρ τὰ ὄμματα αὐγαῖς, καὶ ἡ διάνοια σοφίᾳ περιλάμπεται καὶ ὀξυδερκέστερα ἐμβλέπειν ἐγχριομένη καινοῖς ἀεὶ θεωρήμασιν ἐθίζεται.", "st": "47"}, {"sp": "N", "t": "φωτὸς οὖν ἀνάπαυσις ἑρμηνεύεται Ναχὼρ εἰκότως· ᾗ μὲν γὰρ Ἀβραάμ ἐστι τοῦ σοφοῦ συγγενής, φωτὸς τοῦ κατὰ σοφίαν μετέσχηκεν· ᾗ δ’ οὐ συναποδεδήμηκεν αὐτῷ τὴν ἀπὸ τοῦ γενομένου πρὸς τὸ ἀγένητον καὶ τὴν ἀπὸ τοῦ κόσμου πρὸς τὸν κοσμοπλάστην ἀποδημίαν, χωλὴν καὶ ἀτελῆ τὴν ἐπιστήμην ἐκτήσατο, ἀναπαυομένην καὶ μένουσαν, μᾶλλον δ’ ἀνδριάντος ἀψύχου τρόπον πεπηγυῖαν.", "st": "48"}, {"sp": "N", "t": "τῆς γὰρ Χαλδαϊκῆς οὐ μετανίσταται χώρας, τουτέστι τῆς περὶ ἀστρονομίαν θεωρίας οὐ διαζεύγνυται, τὸ γενόμενον πρὸ τοῦ πεποιηκότος καὶ κόσμον πρὸ θεοῦ τετιμηκώς, μᾶλλον δὲ τὸν κόσμον αὐτὸν θεὸν αὐτοκράτορα νομίζων, οὐκ αὐτοκράτορος ἔργον θεοῦ.", "st": "49"}, {"sp": "N", "t": "Μελχὰν δὲ ἄγεται γυναῖκα, οὐκ ἀνθρώπων ἢ πόλεων ἀφηγουμένην, ἢν τύχῃ, βασιλίδα, ἀλλ’ ὁμώνυμον αὐτὸ μόνον ἐκείνῃ. καθάπερ γὰρ τὸν οὐρανόν, ἅτε κράτιστον ὄντα τῶν γεγονότων, βασιλέα τῶν αἰσθητῶν εἴποι τις ἂν οὐκ ἀπὸ σκοποῦ, οὕτως καὶ τὴν περὶ αὐτὸν ἐπιστήμην, ἣν μετίασιν οἱ ἀστρονομοῦντες καὶ Χαλδαῖοι διαφερόντως, βασιλίδα τῶν ἐπιστημῶν.", "st": "50"}, {"sp": "N", "t": "γυνὴ μὲν οὖν ἥδε ἀστή, παλλακὴ δὲ ἡ ἕν τι τῶν ὄντων ὁρῶσα, κἂν εἰ πάντων εὐτελέστατον ὑπάρχοι. τῷ μὲν οὖν ἀρίστῳ γένει τὸ ἄριστον ὁρᾶν, τὸ ὄντως ὄν, συμβέβηκεν — Ἰσραὴλ γὰρ ὁρῶν θεὸν ἑρμηνεύεται —, τῷ δὲ δευτερείων ἐφιεμένῳ τὸ δεύτερον, τὸν αἰσθητὸν οὐρανὸν καὶ τὴν ἐν αὐτῷ τῶν ἀστέρων ἐναρμόνιον τάξιν καὶ πάμμουσον ὡς ἀληθῶς χορείαν.", "st": "51"}, {"sp": "N", "t": "τρίτοι δέ εἰσιν οἱ σκεπτικοί, τῶν μὲν ἐν τῇ φύσει κρατίστων, αἰσθητῶν τε καὶ νοητῶν, οὐκ ἐφαπτόμενοι, περὶ μικρὰ μέντοι σοφίσματα τριβόμενοι καὶ γλισχρολογούμενοι. τούτοις ἡ ὁρῶσά τι κἂν τὸ σμικρότατον παλλακὶς Ῥουμὰ συνοικεῖ μὴ δυναμένοις πρὸς τὴν τῶν ἀμεινόνων ἐλθεῖν ἔρευναν, ἐξ ὧν τὸν ἑαυτῶν βίον ὀνήσουσιν.", "st": "52"}, {"sp": "N", "t": "ὥσπερ γὰρ ἐν ἰατροῖς ἡ λεγομένη λογιατρεία πολὺ τῆς τῶν καμνόντων ὠφελείας ἀποστατεῖ — φαρμάκοις γὰρ καὶ χειρουργίαις καὶ διαίταις, ἀλλ’ οὐ λόγοις, αἱ νόσοι θεραπεύονται —, οὕτω καὶ ἐν φιλοσοφίᾳ λογοπῶλαι καὶ λογοθῆραί τινες αὐτὸ μόνον εἰσί, τὸν ἀρρωστημάτων γέμοντα βίον θεραπεύειν οὔτε ἐθέλοντες οὔτε ἐπιτηδεύοντες, ἐκ πρώτης δὲ ἡλικίας ἄχρι γήρως ἐσχάτου γνωσιμαχοῦντές τε καὶ συλλαβομαχοῦντες οὐκ ἐρυθριῶσιν, ὥσπερ τῆς εὐδαιμονίας ἐπ’ ὀνομάτων καὶ ῥημάτων [καὶ] ἀπεράντῳ καὶ ἀνηνύτῳ περιεργίᾳ κειμένης, ἀλλ’ οὐκ ἐν τῷ τὸ ἦθος, τὴν τοῦ ἀνθρωπείου βίου πηγήν, ἄμεινον καταστήσασθαι, τὰς μὲν κακίας ὑπερορίους φυγαδεύσαντα αὐτοῦ, τὰς δὲ ἀρετὰς εἰσοικίσαντα.", "st": "53"}, {"sp": "N", "t": "παλλακὰς μέντοι [ἢ] δόξας καὶ δόγματα προσίενται καὶ οἱ φαῦλοι. φησὶ γοῦν ὅτι Θαμνά, ἡ παλλακὴ Ἐλιφὰς τοῦ υἱοῦ Ἠσαῦ, ἔτεκε τῷ Ἐλιφὰς τὸν Ἀμαλήκ. ὢ τῆς τοῦ ἀπογόνου λαμπρᾶς δυσγενείας· ὄψει δὲ αὐτοῦ τὴν δυσγένειαν, ἐὰν ἀποστὰς τοῦ περὶ ἀνθρώπων ταῦτα εἰρῆσθαι νομίζειν τὴν ψυχὴν ὥσπερ ἐξ ἀνατομῆς ἐπισκέπτῃ.", "st": "54"}, {"sp": "N", "t": "τὴν μὲν τοίνυν ἄλογον καὶ ἄμετρον ὁρμὴν τοῦ πάθους Ἀμαλὴκ προσαγορεύει· μεταληφθεὶς γάρ ἐστι λαὸς ἐκλείχων· καθάπερ γὰρ ἡ τοῦ πυρὸς δύναμις τὴν παραβληθεῖσαν ὕλην ἀναλίσκει, τὸν αὐτὸν τρόπον καὶ τὸ πάθος ἀναζέον τὰ ἐν ποσὶ πάντα ἐπιλιχμᾶται καὶ διαφθείρει.", "st": "55"}, {"sp": "N", "t": "τούτου τοῦ πάθους πατὴρ Ἐλιφὰς ἀναγράφεται δεόντως· ἑρμηνεύεται γάρ· θεός με διέσπειρεν. ἀλλ’ οὐχ ὅταν ἀνασκεδάσῃ ἢ διασπείρῃ καὶ σκορακίσῃ τὴν ψυχὴν ἀφ’ ἑαυτοῦ ὁ θεός, τὸ ἄλογον εὐθὺς γεννᾶται πάθος; τὴν μὲν γὰρ ὁρατικὴν αὐτοῦ φιλόθεον ὄντως διάνοιαν, κληματίδα εὐγενῆ, καταφυτεύει ῥίζας ἀποτείνων πρὸς ἀιδιότητα καὶ εὐφορίαν καρπῶν διδοὺς πρὸς κτῆσιν καὶ ἀπόλαυσιν ἀρετῶν.", "st": "56"}, {"sp": "N", "t": "διὸ καὶ Μωυσῆς εὔχεται φάσκων· “εἰσαγαγὼν καταφύτευσον αὐτούς”, ἵνα μὴ ἐφήμερα ἀλλ’ ἀθάνατα καὶ μακραίωνα γένηται τὰ θεῖα βλαστήματα. τὴν δὲ ἄδικον καὶ ἄθεον ψυχὴν φυγαδεύων ἀφ’ ἑαυτοῦ πορρωτάτω διέσπειρεν εἰς τὸν ἡδονῶν καὶ ἐπιθυμιῶν καὶ ἀδικημάτων χῶρον. ὁ δὲ χῶρος οὗτος προσφυέστατα ἀσεβῶν καλεῖται, οὐχ ὁ μυθευόμενος ἐν Ἅιδου· καὶ γὰρ ὁ πρὸς ἀλήθειαν Ἅιδης ὁ τοῦ μοχθηροῦ βίος ἐστίν, ὁ ἀλάστωρ καὶ παλαμναῖος καὶ πάσαις ἀραῖς ἔνοχος.", "st": "57"}, {"sp": "N", "t": "ἔστι δὲ καὶ ἑτέρωθι τὸ γράμμα τοῦτο ἐστηλιτευμένον· “ἡνίκα διεμέριζεν ὁ ὕψιστος ἔθνη, ὡς διέσπειρεν υἱοὺς Ἀδάμ”, τοὺς γηΐνους ἅπαντας τρόπους οὐράνιον οὐδὲν ἀγαθὸν ἐσπουδακότας ἰδεῖν ἤλασεν, ἀοίκους καὶ ἀπόλιδας καὶ σποράδας ὄντως ἐργασάμενος. οὐδενὶ γὰρ τῶν φαύλων οὐκ οἶκος, οὐ πόλις, οὐκ ἄλλο τῶν εἰς κοινωνίαν οὐδὲν διασῴζεται, ἀλλ’ ἀνίδρυτος ὢν σπείρεται, πάντῃ φορούμενος καὶ μετανιστάμενος ἀεὶ καὶ μηδαμόθι στηριχθῆναι δυνάμενος.", "st": "58"}, {"sp": "N", "t": "γίνεται οὖν τῷ φαύλῳ ἐξ ἀστῆς μὲν κακία, τὸ δὲ πάθος ἐκ παλλακῆς. λογισμοῦ γὰρ ἡ μὲν ὅλη ψυχὴ καθάπερ ἀστὴ σύμβιος — ψυχὴ δὲ ἐπίληπτος τίκτει κακίας —, ἡ δὲ τοῦ σώματος φύσις παλλακή, δι’ ἧς ἡ γένεσις τοῦ πάθους θεωρεῖται· ἡδονῶν γὰρ καὶ ἐπιθυμιῶν χώρα τὸ σῶμα.", "st": "59"}, {"sp": "N", "t": "καλεῖται δὲ Θαμνά, ἧς μεταληφθέν ἐστι τοὔνομα ἔκλειψις σαλευομένη· ἐκλείπει γὰρ καὶ ἀδυνατεῖ ἡ ψυχὴ τῷ πάθει, σάλον καὶ κλύδωνα πολὺν ἀπὸ σώματος ἐνδεξαμένη διὰ τὸν καταρραγέντα βαρὺν χειμῶνα ἐξ ἀμετρίας ὁρμῆς.", "st": "60"}, {"sp": "N", "t": "κεφαλὴ δὲ ὡς ζῴου πάντων τῶν λεχθέντων μερῶν ὁ γενάρχης ἐστὶν Ἠσαῦ, ὃς τοτὲ μὲν ποίημα, τοτὲ δὲ δρῦς ἑρμηνεύεται, δρῦς μέν, παρόσον ἀκαμπὴς καὶ ἀνένδοτος ἀπειθής τε καὶ σκληραύχην φύσει, συμβούλῳ χρώμενος ἀνοίᾳ, δρύινος ὄντως, ποίημα δέ, παρόσον πλάσμα καὶ μῦθός ἐστιν ὁ μετὰ ἀφροσύνης βίος, τραγῳδίας καὶ κενοῦ κόμπου καὶ πάλιν γέλωτος καὶ κωμικῆς χλεύης ἀνάπλεως, ὑγιὲς ἔχων οὐδέν, κατεψευσμένος, ἐκτετοξευκὼς ἀλήθειαν, τὴν ἄποιον καὶ ἀνείδεον καὶ ἄπλαστον φύσιν ἐν οὐδενὶ λόγῳ τιθέμενος, ἧς ὁ ἀσκητὴς ἐρᾷ.", "st": "61"}, {"sp": "N", "t": "μαρτυρεῖ δὲ Μωυσῆς φάσκων, ὅτι “ἦν Ἰακὼβ ἄπλαστος, οἰκῶν οἰκίαν”, ὥστε ὁ ἐναντίος τούτῳ ἄοικος ἂν εἴη, πλάσματος καὶ ποιήματος καὶ μυθικῶν λήρων ἑταῖρος, μᾶλλον δὲ σκηνὴ καὶ μῦθος αὐτός.", "st": "62"}, {"sp": "N", "t": "Ἡ μὲν δὴ λογισμοῦ φιλοθεάμονος πρὸς ἀστὰς καὶ παλλακίδας δυνάμεις σύνοδος, ὡς οἷόν τε ἦν, εἴρηται· τὸν δ’ εἱρμὸν τοῦ λόγου συνυφαντέον τἀκόλουθα διερευνῶντας. “ὑπήκουσε” φησίν “Ἀβραὰμ τῆς φωνῆς Σάρρας”· ἀναγκαῖον γὰρ τοῖς παραγγέλμασιν ἀρετῆς τὸν μανθάνοντα πειθαρχεῖν.", "st": "63"}, {"sp": "N", "t": "οὐ πάντες δὲ πειθαρχοῦσιν, ἀλλ’ ὅσοις σφοδρὸς ἔρως ἐντέτηκεν ἐπιστήμης· ἐπεὶ καθ’ ἑκάστην σχεδὸν ἡμέραν τά τε ἀκροατήρια καὶ τὰ θέατρα πληροῦται, διεξέρχονται δὲ ἀπνευστὶ συνείροντες τοὺς περὶ ἀρετῆς λόγους οἱ φιλοσοφοῦντες.", "st": "64"}, {"sp": "N", "t": "ἀλλὰ τί τῶν λεγομένων ὄφελος; ἀντὶ γὰρ τοῦ προσέχειν ἑτέρωσε τὸν νοῦν ἀποστείλαντες οἱ μὲν πλοῦ καὶ ἐμπορίας, οἱ δὲ προσόδων καὶ γεωργίας, οἱ δὲ τιμῶν καὶ πολιτείας, οἱ δὲ τῶν ἀφ’ ἑκάστης τέχνης καὶ ἐπιτηδεύσεως κερδῶν, ἄλλοι δὲ τιμωρίας ἐχθρῶν, οἱ δὲ τῶν ἐν ταῖς ἐρωτικαῖς ἐπιθυμίαις ἀπολαύσεων καὶ συνόλως ἑτέρων ἕτεροι διαμέμνηνται, ὡς ἕνεκα τῶν ἐπιδεικνυμένων κεκωφῆσθαι, τοῖς μὲν σώμασι παρεῖναι μόνον, ταῖς δὲ διανοίαις ἀπηλλάχθαι, εἰδώλων καὶ ἀνδριάντων διαφέρειν μηδέν.", "st": "65"}, {"sp": "N", "t": "εἰ δέ τινες καὶ προσέχουσι, τοσοῦτον χρόνον καθέζονται μόνον ἀκούοντες, ἀπαλλαγέντες δ’ οὐδενὸς τῶν εἰρημένων διαμέμνηνται, καὶ ἧκον τερφθῆναι δι’ ἀκοῆς μᾶλλον ἢ ὠφεληθῆναι· ὥστε οὐδὲν αὐτῶν ἴσχυσεν ἡ ψυχὴ συλλαβεῖν καὶ κυοφορῆσαι, ἀλλ’ ἅμα τὸ κινοῦν τὴν ἡδονὴν αἴτιον ἡσύχασε καὶ ἡ προσοχὴ κατεσβέσθη.", "st": "66"}, {"sp": "N", "t": "τρίτοι δέ εἰσιν οἷς ἔναυλα μὲν τὰ λεχθέντα ὑπηχεῖ, σοφισταὶ δὲ ἀντὶ φιλοσόφων ἀνευρίσκονται. τούτων ὁ μὲν λόγος ἐπαινετός, ὁ δὲ βίος ψεκτός ἐστι· δυνατοὶ μὲν γὰρ εἰπεῖν, ἀδύνατοι δέ εἰσι πράττειν τὰ βέλτιστα.", "st": "67"}, {"sp": "N", "t": "μόλις οὖν ἔστιν εὑρεῖν προσεκτικὸν καὶ μνημονικόν, τὸ πράττειν τοῦ λέγειν προτιμῶντα, ἃ δὴ μαρτυρεῖται τῷ φιλομαθεῖ διὰ τοῦ “ὑπήκουσε τῆς φωνῆς Σάρρας.” οὐ γὰρ ἀκούων ἀλλ’ ὑπακούων εἰσάγεται· τὸ δέ ἐστι τοῦ συναινεῖν καὶ πειθαρχεῖν εὐθυβολώτατον ὄνομα.", "st": "68"}, {"sp": "N", "t": "οὐκ ἀπὸ σκοποῦ δὲ πρόσκειται τὸ “τῆς φωνῆς”, ἀλλὰ μὴ τῆς φωνούσης Σάρρας ὑπακοῦσαι. ἴδιον γὰρ τοῦ μανθάνοντος φωνῆς καὶ λόγων ἀκροᾶσθαι, διδάσκεται γὰρ τούτοις μόνοις· ὁ δὲ ἀσκήσει τὸ καλὸν ἀλλὰ μὴ διδασκαλίᾳ κτώμενος οὐ τοῖς λεγομένοις ἀλλὰ τοῖς λέγουσι προσέχει, μιμούμενος τὸν ἐκείνων βίον ἐν ταῖς κατὰ μέρος ἀνεπιλήπτοις πράξεσι.", "st": "69"}, {"sp": "N", "t": "λέγεται γὰρ ἐπὶ τοῦ Ἰακώβ, ἡνίκα εἰς τὸν συγγενικὸν γάμον πέμπεται· “εἰσήκουσεν Ἰακὼβ τοῦ πατρὸς καὶ τῆς μητρὸς αὐτοῦ, καὶ ἐπορεύθη εἰς τὴν Μεσοποταμίαν”, οὐ τῆς φωνῆς οὐδὲ τῶν λόγων — τοῦ γὰρ βίου μιμητὴν ἔδει τὸν ἀσκητήν, οὐκ ἀκροατὴν λόγων εἶναι· τοῦτο μὲν γὰρ ἴδιον τοῦ διδασκομένου, ἐκεῖνο δὲ τοῦ διαθλοῦντος —, ἵνα κἀνταῦθα διαφορὰν ἀσκητοῦ καὶ μανθάνοντος καταλάβωμεν, τοῦ μὲν κοσμουμένου κατὰ τὸν λέγοντα, τοῦ δὲ κατὰ τὸν ἐκείνου λόγον.", "st": "70"}, {"sp": "N", "t": "“Λαβοῦσα” οὖν φησι “Σάρρα ἡ γυνὴ Ἀβραὰμ Ἄγαρ τὴν Αἰγυπτίαν, τὴν ἑαυτῆς παιδίσκην, μετὰ δέκα ἔτη τοῦ οἰκῆσαι Ἀβραὰμ ἐν γῇ Χαναάν, ἔδωκε τῷ Ἀβραὰμ τῷ ἀνδρὶ αὐτῆς αὐτῷ γυναῖκα”. βάσκανον μὲν καὶ πικρὸν καὶ κακόηθες φύσει κακία, ἥμερον δὲ καὶ κοινωνικὸν καὶ εὐμενὲς ἀρετή, πάντα τρόπον τοὺς εὐφυῶς ἔχοντας ὠφελεῖν ἢ δι’ αὐτῆς ἢ δι’ ἑτέρων ἐθέλουσα.", "st": "71"}, {"sp": "N", "t": "νυνὶ γοῦν μήπω δυναμένοις ἡμῖν ἐκ φρονήσεως παιδοποιεῖσθαι τὴν ἑαυτῆς ἐγγυᾷ θεραπαινίδα, τὴν ἐγκύκλιον, ὡς ἔφην, παιδείαν, καὶ μονονοὺ προξενεῖν καὶ νυμφοστολεῖν ὑπομένει· αὐτὴ γὰρ λέγεται λαβοῦσα διδόναι τῷ ἀνδρὶ αὐτῆς γυναῖκα ταύτην.", "st": "72"}, {"sp": "N", "t": "ἄξιον δὲ διαπορῆσαι, διὰ τί νυνὶ πάλιν γυναῖκα τοῦ Ἀβραὰμ εἶπε τὴν Σάρραν, πολλάκις ἤδη πρότερον μεμηνυκώς· οὐ γὰρ μακρολογίας τὸ φαυλότατον εἶδος, ταυτολογίαν, ἐπιτετήδευκε. τί οὖν λεκτέον; ἐπειδὴ μέλλει τὴν θεραπαινίδα φρονήσεως, τὴν ἐγκύκλιον παιδείαν, ἐγγυᾶσθαι, φησὶν ὅτι οὐκ ἐξελάθετο τῶν πρὸς τὴν δέσποιναν αὐτῆς ὁμολογιῶν, ἀλλ’ οἶδε μὲν ἐκείνην ἑαυτοῦ νόμῳ καὶ γνώμῃ γυναῖκα, ταύτην δὲ ἀνάγκῃ καὶ βίᾳ καιροῦ. τοῦτο δὲ παντὶ συμβαίνει φιλομαθεῖ·", "st": "73"}, {"sp": "N", "t": "μάρτυς δ’ ὁ πεπονθὼς γένοιτ’ ἂν ἀψευδέστατος. ἐγὼ γοῦν ἡνίκα πρῶτον κέντροις φιλοσοφίας πρὸς τὸν πόθον αὐτῆς ἀνηρεθίσθην, ὡμίλησα κομιδῇ νέος ὢν μιᾷ τῶν θεραπαινίδων αὐτῆς, γραμματικῇ, καὶ ὅσα ἐγέννησα ἐκ ταύτης, τὸ γράφειν, τὸ ἀναγινώσκειν, τὴν ἱστορίαν τῶν παρὰ ποιηταῖς, ἀνέθηκα τῇ δεσποίνῃ.", "st": "74"}, {"sp": "N", "t": "καὶ πάλιν ἑτέρᾳ συνελθών, γεωμετρίᾳ, καὶ τοῦ κάλλους ἀγάμενος — εἶχε γὰρ συμμετρίαν καὶ ἀναλογίαν ἐν τοῖς μέρεσι πᾶσι — τῶν ἐγγόνων οὐδὲν ἐνοσφισάμην, ἀλλὰ τῇ", "st": "75"}, {"sp": "N", "t": "ἀστῇ φέρων ἐδωρησάμην. ἐσπούδασα καὶ τρίτῃ συνελθεῖν — ἦν δὲ εὔρυθμος, εὐάρμοστος, ἐμμελής, μουσικὴ δὲ ἐκαλεῖτο — καὶ ἐγέννησα ἐξ αὐτῆς διατονικὰ χρώματα καὶ ἐναρμόνια, συνημμένα, διεζευγμένα μέλη, τῆς διὰ τεττάρων, τῆς διὰ πέντε, τῆς διὰ πασῶν συμφωνίας ἐχόμενα, καὶ πάλιν οὐδὲν αὐτῶν ἀπεκρυψάμην, ἵνα πλουσία μοι γένηται ἡ ἀστὴ γυνή, μυρίων οἰκετῶν ὑπηρετουμένη πλήθει.", "st": "76"}, {"sp": "N", "t": "τινὲς γὰρ τοῖς φίλτροις τῶν θεραπαινίδων δελεασθέντες ὠλιγώρησαν τῆς δεσποίνης, φιλοσοφίας, καὶ κατεγήρασαν οἱ μὲν ἐν ποιήμασιν, οἱ δὲ ἐν γραμμαῖς, οἱ δὲ ἐν χρωμάτων κράσεσιν, οἱ δὲ ἐν ἄλλοις μυρίοις, οὐ δυνηθέντες ἐπὶ τὴν ἀστὴν ἀναδραμεῖν.", "st": "77"}, {"sp": "N", "t": "ἔχει γὰρ ἑκάστη τέχνη γλαφυρότητας, ὁλκούς τινας δυνάμεις, ὑφ’ ὧν ἔνιοι ψυχαγωγούμενοι καταμένουσιν, ἐκλελησμένοι τῶν πρὸς φιλοσοφίαν ὁμολογιῶν. ὁ δὲ ἐμμένων ταῖς συνθήκαις πορίζει πάντα πανταχόθεν πρὸς τὴν ἀρέσκειαν αὐτῆς. εἰκότως οὖν τῆς πίστεως αὐτὸν ἀγάμενος ὁ ἱερὸς λόγος φησίν, ὅτι καὶ νῦν ἦν αὐτῷ γυνὴ Σάρρα, ὅτε τὴν θεραπαινίδα πρὸς τὴν ἐκείνης ἀρέσκειαν ἠγάγετο.", "st": "78"}, {"sp": "N", "t": "καὶ μὴν ὥσπερ τὰ ἐγκύκλια συμβάλλεται πρὸς φιλοσοφίας ἀνάληψιν, οὕτω καὶ φιλοσοφία πρὸς σοφίας κτῆσιν. ἔστι γὰρ φιλοσοφία ἐπιτήδευσις σοφίας, σοφία δὲ ἐπιστήμη θείων καὶ ἀνθρωπίνων καὶ τῶν τούτων αἰτίων. γένοιτ’ ἂν οὖν ὥσπερ ἡ ἐγκύκλιος μουσικὴ φιλοσοφίας, οὕτω καὶ φιλοσοφία δούλη σοφίας.", "st": "79"}, {"sp": "N", "t": "φιλοσοφία δὲ ἐγκράτειαν μὲν γαστρός, ἐγκράτειαν δὲ τῶν μετὰ γαστέρα, ἐγκράτειαν δὲ καὶ γλώττης ἀναδιδάσκει. ταῦτα λέγεται μὲν εἶναι δι’ αὑτὰ αἱρετά, σεμνότερα δὲ φαίνοιτ’ ἄν, εἰ θεοῦ τιμῆς καὶ ἀρεσκείας ἕνεκα ἐπιτηδεύοιτο. μεμνῆσθαι οὖν δεῖ τῆς κυρίας, ὁπότε μέλλοιμεν αὐτῆς τὰς θεραπαινίδας μνᾶσθαι· καὶ λεγώμεθα μὲν ἄνδρες εἶναι τούτων, ὑπαρχέτω δ’ ἡμῖν ἐκείνη πρὸς ἀλήθειαν γυνή, μὴ λεγέσθω.", "st": "80"}, {"sp": "N", "t": "Δίδωσι δ’ οὐκ εὐθὺς εἰς τὴν Χαναναίων γῆν ἀφικομένῳ, ἀλλὰ μετὰ δεκαετίαν τῆς ἐκεῖ διατριβῆς. τί δὲ τοῦτ’ ἐστίν, οὐκ ἀμελῶς ἐπισκεπτέον· ἐν ἀρχῇ μὲν τῆς γενέσεως ἡμῶν ἡ ψυχὴ συντρόφοις τοῖς πάθεσι μόνοις χρῆται, λύπαις, ἀλγηδόσι, πτόαις, ἐπιθυμίαις, ἡδοναῖς, ἃ διὰ τῶν αἰσθήσεων ἐπ’ αὐτὴν ἔρχεται, μήπω τοῦ λογισμοῦ βλέπειν δυναμένου τά τε ἀγαθὰ καὶ κακὰ καὶ ᾗ διαφέρει ταῦτα ἀλλήλων ἀκριβοῦν, ἀλλ’ ἔτι νυστάζοντος καὶ ὡς ἐν ὕπνῳ βαθεῖ καταμεμυκότος.", "st": "81"}, {"sp": "N", "t": "χρόνου δὲ προϊόντος ὅταν ἐκβαίνοντες τῆς παιδικῆς ἡλικίας μειρακιοῦσθαι μέλλωμεν, τὸ δίδυμον στέλεχος εὐθὺς ἐκ μιᾶς, ἀρετὴ καὶ κακία, φύεται ῥίζης· καὶ ποιούμεθα μὲν τὴν κατάληψιν ἀμφοῖν, αἱρούμεθα δὲ πάντως τὴν ἑτέραν, οἱ μὲν εὐφυεῖς ἀρετήν, κακίαν δ’ οἱ ἐναντίοι.", "st": "82"}, {"sp": "N", "t": "τούτων προϋποτυπωθέντων εἰδέναι χρή, ὅτι παθῶν μὲν Αἴγυπτος σύμβολόν ἐστι, κακιῶν δὲ ἡ Χαναναίων γῆ· ὥστ’ εἰκότως ἀναστήσας ἀπ’ Αἰγύπτου τὸν λεὼν εἰς τὴν Χαναναίων εἰσάγει χώραν.", "st": "83"}, {"sp": "N", "t": "ἄνθρωπος γάρ, ὡς ἔφην, ἅμα μὲν τῇ γενέσει τὸ Αἰγύπτιον πάθος ἔλαχεν οἰκεῖν ἡδοναῖς καὶ ἀλγηδόσι προσερριζωμένος, αὖθις δ’ ἀποικίαν στέλλεται τὴν πρὸς κακίαν, ἤδη τοῦ λογισμοῦ πρὸς τὸ ὀξυωπέστερον ἐπιδεδωκότος καὶ καταλαμβάνοντος μὲν ἀμφότερα, ἀγαθόν τε αὖ καὶ κακόν, τὸ δὲ χεῖρον αἱρουμένου διὰ τὸ πολὺ μετέχειν τοῦ θνητοῦ, ᾧ τὸ κακὸν οἰκεῖον, ἐπεὶ καὶ τοὐναντίον τῷ θείῳ, τὸ ἀγαθόν.", "st": "84"}, {"sp": "N", "t": "ἀλλ’ αἱ μὲν φύσει πατρίδες αὗται, παιδικῆς μὲν ἡλικίας τὸ πάθος, Αἴγυπτος, ἡβώσης δὲ κακία, ἡ Χανανῖτις. ὁ δὲ ἱερὸς λόγος, καίτοι σαφῶς ἐπιστάμενος τὰς τοῦ θνητοῦ γένους πατρίδας ἡμῶν, ὑποτίθεται τὰ πρακτέα καὶ συνοίσοντα παραγγέλλων μισεῖν τὰ ἔθη καὶ τὰ νόμιμα καὶ τὰ ἐπιτηδεύματα αὐτῶν ἐν οἷς φησι· “καὶ εἶπε κύριος πρὸς Μωυσῆν λέγων·", "st": "85"}, {"sp": "N", "t": "λάλησον τοῖς υἱοῖς Ἰσραὴλ καὶ ἐρεῖς πρὸς αὐτούς· ἐγὼ κύριος ὁ θεὸς ὑμῶν· κατὰ τὰ ἐπιτηδεύματα γῆς Αἰγύπτου, ἐν ᾗ κατοικήσατε ἐπ’ αὐτῆς, οὐ ποιήσετε· καὶ κατὰ τὰ ἐπιτηδεύματα γῆς Χαναάν, εἰς ἣν ἐγὼ εἰσάγω ὑμᾶς ἐκεῖ, οὐ ποιήσετε· καὶ τοῖς νομίμοις αὐτῶν οὐ πορεύσεσθε· τὰ κρίματά μου ποιήσετε, καὶ τὰ προστάγματά μου φυλάξεσθε, πορεύεσθε ἐν αὐτοῖς· ἐγὼ κύριος ὁ θεὸς ὑμῶν. καὶ φυλάξεσθε πάντα τὰ προστάγματά μου καὶ τὰ κρίματά μου, καὶ ποιήσετε αὐτά. ὁ ποιήσας αὐτὰ ζήσεται ἐν αὐτοῖς· ἐγὼ κύριος ὁ θεὸς ὑμῶν”.", "st": "86"}, {"sp": "N", "t": "οὐκοῦν ἡ πρὸς ἀλήθειαν ζωὴ περιπατοῦντός ἐστιν ἐν ταῖς τοῦ θεοῦ κρίσεσι καὶ προστάξεσιν, ὥστε θάνατος ἂν εἴη τὰ τῶν ἀθέων ἐπιτηδεύματα. τινὰ δὲ ἀθεώρητα πάθους καὶ κακιῶν ἐστιν, ἐξ ὧν τὰ ἀσεβῶν καὶ ἀνοσιουργῶν πλήθη φύεται.", "st": "87"}, {"sp": "N", "t": "μετὰ δεκαετίαν οὖν τῆς πρὸς Χαναναίους μετοικίας ἀξόμεθα τὴν Ἄγαρ, ἐπειδήπερ εὐθὺς μὲν γενόμενοι λογικοὶ τῆς φύσει βλαβερᾶς ἀμαθίας καὶ ἀπαιδευσίας μεταποιούμεθα, χρόνῳ δ’ ὕστερον καὶ ἐν ἀριθμῷ τελείῳ, δεκάδι, νομίμου παιδείας τῆς ὠφελεῖν δυναμένης εἰς ἐπιθυμίαν ἐρχόμεθα.", "st": "88"}, {"sp": "N", "t": "Τὸν δὲ περὶ δεκάδος λόγον ἐπιμελῶς μὲν ἠκρίβωσαν μουσικῶν παῖδες, ὕμνησε δὲ οὐ μετρίως ὁ ἱερώτατος Μωυσῆς, ἀναθεὶς αὐτῇ τὰ κάλλιστα, τὰς ἀρχάς, τὰς ἀπαρχάς, τὰ τῶν ἱερέων ἐνδελεχῆ δῶρα, τὴν τοῦ Πάσχα διατήρησιν, τὸν ἱλασμόν, τὴν διὰ πεντηκονταετίας ἄφεσίν τε καὶ εἰς τὰς ἀρχαίας λήξεις ἐπάνοδον, τὴν κατασκευὴν τῆς ἀδιαλύτου σκηνῆς, ἄλλα μυρία, ὧν μακρὸν ἂν εἴη μεμνῆσθαι.", "st": "89"}, {"sp": "N", "t": "τὰ δὲ καίρια οὐ παρετέον. αὐτίκα τὸν Νῶε ἡμῖν — πρῶτος δ’ οὗτος δίκαιος ἐν ταῖς ἱεραῖς ἀνερρήθη γραφαῖς — ἀπὸ τοῦ διαπλασθέντος ἐκ γῆς εἰσάγει δέκατον, οὐκ ἐνιαυτῶν πλῆθος παραστῆσαι βουλόμενος, ἀλλὰ διδάξαι σαφῶς, ὅτι ὥσπερ δεκὰς ἀριθμῶν τῶν ἀπὸ μονάδος ἐστὶ πέρας τελειότατον, οὕτω τὸ δίκαιον ἐν ψυχῇ τέλειον καὶ πέρας ὄντως τῶν κατὰ τὸν βίον πράξεων.", "st": "90"}, {"sp": "N", "t": "τὴν μὲν γὰρ πολλαπλασιαζομένην ἐφ’ ἑαυτὴν τριάδα πρὸς ἐνάτου γένεσιν ἀριθμοῦ πολεμιωτάτην ἐξεῖπον οἱ χρησμοί, τὴν δὲ ἐπιβεβηκυῖαν μονάδα πρὸς ἐκπλήρωσιν δεκάδος ὡς φίλην ἀπεδέξαντο.", "st": "91"}, {"sp": "N", "t": "σημεῖον δέ· τὰς ἐννέα τῶν βασιλέων ἀρχάς, ἡνίκα ἡ ἐμφύλιος ἀνερριπίσθη στάσις, τῶν τεττάρων παθῶν πρὸς τὰς πέντε αἰσθήσεις κονισαμένων καὶ πόρθησιν καὶ κατασκαφὴν κινδυνευούσης τρόπον πόλεως τῆς ὅλης ἀναδέχεσθαι ψυχῆς, ἐκστρατεύσας ὁ σοφὸς Ἀβραὰμ κατέλυσε δέκατος ἐπιφανείς.", "st": "92"}, {"sp": "N", "t": "οὗτος ἀντὶ χειμῶνος γαλήνην καὶ ὑγείαν ἀντὶ νόσου καὶ ζωήν, εἰ δεῖ τἀληθὲς εἰπεῖν, ἀντὶ θανάτου παρεσκεύασε, τοῦ νικηφόρου θεοῦ τροπαιοφόρον αὐτὸν ἀναδείξαντος, ᾧ καὶ τὰς δεκάτας χαριστήρια τῆς νίκης ἀνατίθησι.", "st": "93"}, {"sp": "N", "t": "καὶ παντὸς μέντοι τοῦ ἐλθόντος “ὑπὸ τὴν ῥάβδον,” λέγω δὲ τὴν παιδείαν, ἡμέρου καὶ τιθασοῦ θρέμματος τὸ δέκατον ἀποκρίνεται, νόμου προστάξει γινόμενον “ἅγιον”, ἵν’ ἐκ πολλῶν διδασκώμεθα τὴν δεκάδος πρὸς θεὸν οἰκειότητα καὶ τὴν τοῦ ἐννέα ἀριθμοῦ πρὸς τὸ θνητὸν ἡμῶν γένος.", "st": "94"}, {"sp": "N", "t": "ἀλλὰ γὰρ οὐκ ἀπὸ ζῴων μόνον ἀπάρχεσθαι δεκάτας, ἀλλὰ καὶ ἀπὸ τῶν ὅσα ἐκ γῆς βλαστάνει διείρηται. “πᾶσα” γάρ φησι “δεκάτη τῆς γῆς ἀπὸ τοῦ σπέρματος καὶ τοῦ καρποῦ τοῦ ξυλίνου ἐστὶν ἅγιον τῷ κυρίῳ· καὶ πᾶσα δεκάτη βοῶν καὶ προβάτων, καὶ πᾶν ὃ ἂν διέλθῃ ἐν τῷ ἀριθμῷ ὑπὸ τὴν ῥάβδον, τὸ δέκατον ἔσται ἅγιον τῷ κυρίῳ”.", "st": "95"}, {"sp": "N", "t": "ὁρᾷς ὅτι καὶ ἀπὸ τοῦ περὶ ἡμᾶς ὄγκου σωματικοῦ, ὃς γεώδης καὶ ξύλινος ὄντως ἐστίν, οἴεται δεῖν ἀπάρχεσθαι; ἡ γὰρ ζωὴ καὶ διαμονὴ καὶ αὔξησις καὶ ὑγίεια αὐτῷ θείᾳ γίνεται χάριτι. ὁρᾷς δ’ ὅτι καὶ ἀπὸ τῶν ἐν ἡμῖν αὐτοῖς ζῴων ἀλόγων — ταῦτα δ’ εἰσὶν αἰσθήσεις — πάλιν ἀπάρχεσθαι διείρηται; τὸ γὰρ ὁρᾶν καὶ ἀκούειν καὶ ὀσφραίνεσθαι καὶ γεύεσθαι, ἔτι δὲ ἅπτεσθαι δωρεαὶ θεῖαι, ὑπὲρ ὧν εὐχαριστητέον.", "st": "96"}, {"sp": "N", "t": "ἀλλὰ γὰρ οὐ μόνον ἐπὶ τοῖς ξυλίνοις καὶ γηίνοις σώματος ὄγκοις οὐδ’ ἐπ’ ἀλόγοις ζῴοις, ταῖς αἰσθήσεσι, τὸν εὐεργέτην ἐπαινεῖν διδασκόμεθα, ἀλλὰ καὶ ἐπὶ τῷ νῷ, ὃς κυρίως εἰπεῖν ἄνθρωπός ἐστιν ἐν ἀνθρώπῳ, κρείττων ἐν χείρονι καὶ ἀθάνατος ἐν θνητῷ.", "st": "97"}, {"sp": "N", "t": "διὰ τοῦτο οἶμαι τὰ πρωτότοκα καθιέρωσε πάντα, τὴν δεκάτην, λέγω Λευιτικὴν φυλήν, ἀντικαταλλαξάμενος πρὸς διατήρησιν καὶ φυλακὴν ὁσιότητος καὶ εὐσεβείας καὶ λειτουργιῶν, αἳ πρὸς τὴν τοῦ θεοῦ τιμὴν ἀναφέρονται. τὸ γὰρ πρῶτον καὶ ἄριστον ἐν ἡμῖν αὐτοῖς ὁ λογισμός ἐστι, καὶ ἄξιον τὰς συνέσεως καὶ ἀγχινοίας καταλήψεώς τε καὶ φρονήσεως καὶ τῶν ἄλλων δυνάμεων, ὅσαι περὶ αὐτόν εἰσιν, ἀπαρχὰς ἀνατιθέναι θεῷ τῷ τὴν εὐφορίαν τοῦ διανοεῖσθαι παρασχόντι.", "st": "98"}, {"sp": "N", "t": "ἐνθένδε ὁ μὲν ἀσκητικὸς ὁρμηθεὶς εὐχόμενος εἶπε· “πάντων ὧν ἄν μοι δῷς, δεκάτην ἀποδεκατώσω σοί”, ὁ δὲ χρησμὸς ὁ μετὰ τὰς ἐπινικίους εὐχὰς ἀναγραφείς, ἃς ὁ τὴν αὐτομαθῆ καὶ αὐτοδίδακτον λαχὼν ἱερωσύνην ποιεῖται Μελχισεδέκ, “ἔδωκε γὰρ αὐτῷ” φησίν “δεκάτην ἀπὸ πάντων”, ἀπὸ τῶν κατ’ αἴθησιν τὸ καλῶς αἰσθάνεσθαι, ἀπὸ τῶν κατὰ λόγον τὸ εὖ λέγειν, ἀπὸ τῶν κατὰ νοῦν τὸ εὖ διανοεῖσθαι.", "st": "99"}, {"sp": "N", "t": "παγκάλως οὖν καὶ ἀναγκαίως ἅμα ἐν εἴδει παραδιηγήματος, ἡνίκα τῆς οὐρανίου καὶ θείας τροφῆς τὸ μνημεῖον ἐν στάμνῳ χρυσῷ καθιεροῦτο, φησὶν ὡς ἄρα “τὸ γομὸρ τὸ δέκατον τῶν τριῶν μέτρων ἦν”. ἐν ἡμῖν γὰρ αὐτοῖς τρία μέτρα εἶναι δοκεῖ, αἴσθησις, λόγος, νοῦς· αἰσθητῶν μὲν αἴσθησις, ὀνομάτων δὲ καὶ ῥημάτων καὶ τῶν λεγομένων ὁ λόγος, νοητῶν δὲ νοῦς.", "st": "100"}, {"sp": "N", "t": "ἀφ’ ἑκάστου δὴ τῶν τριῶν μέτρων τούτων ἀπαρκτέον ὥσπερ τινὰ ἱερὰν δεκάτην, ἵνα καὶ τὸ λέγειν καὶ τὸ αἰσθάνεσθαι καὶ τὸ καταλαμβάνειν ἀνυπαιτίως καὶ ὑγιεινῶς κατὰ θεὸν ἐξετάζηται· τὸ γὰρ ἀληθινὸν καὶ δίκαιον μέτρον τοῦτ’ ἐστί, τὰ δὲ", "st": "101"}, {"sp": "N", "t": "καθ’ ἡμᾶς ψευδῆ τε καὶ ἄδικα. εἰκότως οὖν καὶ ἐπὶ τῶν θυσιῶν τὸ μὲν δέκατον τοῦ μέτρου τῆς σεμιδάλεως τοῖς ἱερείοις ἐπὶ τὸν βωμὸν συνανενεχθήσεται, ὁ δὲ ἔνατος ἀριθμός, τὸ λείψανον τοῦ δεκάτου, παρ’ ἡμῖν αὐτοῖς παραμενεῖ.", "st": "102"}, {"sp": "N", "t": "τούτοις συνᾴδει καὶ ἡ τῶν ἱερέων ἐνδελεχὴς θυσία· τὸ γὰρ δέκατον τὸ τοῦ οἶφι σεμιδάλεως ἀεὶ διείρηται προσφέρειν αὐτοῖς. ἔμαθον γὰρ τὸν ἔνατον ὑπερβαίνοντες αἰσθητὸν δοκήσει θεὸν τὸν δέκατον καὶ μόνον ὄντα ἀψευδῶς προσκυνεῖν. ἐννέα γὰρ ὁ κόσμος ἔλαχε μοίρας,", "st": "103"}, {"sp": "N", "t": "ἐν οὐρανῷ μὲν ὀκτώ, τήν τε ἀπλανῆ καὶ ἑπτὰ τὰς πεπλανημένας ἐν τάξεσι φερομένας ταῖς αὐταῖς, ἐνάτην δὲ γῆν σὺν ὕδατι καὶ ἀέρι· τούτων γὰρ μία συγγένεια τροπὰς καὶ μεταβολὰς παντοίας δεχομένων.", "st": "104"}, {"sp": "N", "t": "οἱ μὲν οὖν πολλοὶ τὰς ἐννέα ταύτας μοίρας καὶ τὸν παγέντα κόσμον ἐξ αὐτῶν ἐτίμησαν, ὁ δὲ τέλειος τὸν ὑπεράνω τῶν ἐννέα, δημιουργὸν αὐτῶν, δέκατον θεόν· ὅλον γὰρ ὑπερκύψας τὸ ἔργον ἐπόθει τὸν τεχνίτην, καὶ ἱκέτης καὶ θεραπευτὴς ἐσπούδαζεν αὐτοῦ γενέσθαι· διὰ τοῦτο δεκάτην ἐνδελεχῆ τῷ δεκάτῳ καὶ μόνῳ καὶ αἰωνίῳ ὁ ἱερεὺς ἀνατίθησι.", "st": "105"}, {"sp": "N", "t": "τοῦτ’ ἐστὶ κυρίως εἰπεῖν τὸ ψυχικὸν Πάσχα, ἡ ἀπὸ παντὸς πάθους καὶ παντὸς αἰσθητοῦ διάβασις πρὸς τὸ δέκατον, ὃ δὴ νοητόν ἐστι καὶ θεῖον· λέγεται γάρ· “δεκάτῃ τοῦ μηνὸς τούτου λαβέτωσαν ἕκαστος πρόβατον κατ’ οἰκίαν”, ἵνα ἀπὸ τῆς δεκάτης τῷ δεκάτῳ καθιερωθῇ τὰ θύματα διατηρηθέντα ἐν τῇ ψυχῇ κατὰ δύο μοίρας ἐκ τριῶν πεφωτισμένῃ, μέχρις ἂν ὅλη δι’ ὅλων γενομένη φέγγος οὐράνιον, οἷα πλησιφαὴς σελήνη κατὰ δευτέρας ἑβδομάδος παραύξησιν, μὴ μόνον φυλάττειν ἀλλὰ καὶ ἱερουργεῖν ἤδη δύνηται τὰς ἀσινεῖς καὶ ἀμώμους προκοπάς.", "st": "106"}, {"sp": "N", "t": "τοῦτ’ ἐστὶν ἱλασμός — καὶ γὰρ οὗτος δεκάτῃ τοῦ μηνὸς βεβαιοῦται, τὸν δέκατον ἱκετευούσης θεὸν ψυχῆς καὶ τὴν ταπεινότητα καὶ οὐδένειαν τοῦ γενητοῦ περίνοιαν λογισμοῦ πεποιθυίας καὶ τὰς ἐν ἅπασι τοῖς καλοῖς ὑπερβολὰς καὶ ἀκρότητας τοῦ ἀγενήτου δεδιδαγμένης. ἵλεως οὖν καὶ ἄνευ ἱκετείας ἵλεως εὐθὺς γίνεται τοῖς ἑαυτοὺς κακοῦσι καὶ συστέλλουσι καὶ μὴ καυχήσει καὶ οἰήσει φυσωμένοις —, τοῦτ’ ἐστὶν ἄφεσις,", "st": "107"}, {"sp": "N", "t": "τοῦτ’ ἐλευθερία παντελὴς ψυχῆς ὃν ἐπλανήθη τε πλάνον ἀποσειομένης καὶ πρὸς τὴν ἀπλανῆ φύσιν μεθορμιζομένης καὶ ἐπὶ τοὺς κλήρους ἐπανιούσης, οὓς ἔλαχεν, ἡνίκα λαμπρὸν ἔπνει καὶ τοὺς περὶ τῶν καλῶν πόνους ἤθλει. τότε γὰρ αὐτὴν τῶν ἄθλων ἀγάμενος ὁ ἱερὸς λόγος ἐτίμησε, γέρας ἐξαίρετον δούς, κλῆρον ἀθάνατον, τὴν ἐν ἀφθάρτῳ γένει τάξιν.", "st": "108"}, {"sp": "N", "t": "τοῦτο καὶ Ἀβραὰμ ὁ σοφὸς ἱκετεύει, μελλούσης ἐμπίπρασθαι λόγῳ μὲν τῆς Σοδομίτιδος γῆς, ἔργῳ δὲ τῆς ἐστειρωμένης τὰ καλὰ καὶ τυφλῆς τὸν λογισμὸν ψυχῆς, ἵν’, ἐὰν εὑρεθῇ τὸ δικαιοσύνης μνημεῖον, ἡ δεκάς, ἐν αὐτῇ, τύχῃ τινὸς ἀμνηστίας· ἄρχεται μὲν οὖν τῆς ἱκεσίας ἀπὸ τοῦ τῆς ἀφέσεως ἀριθμοῦ, πεντηκοντάδος, λήγει δὲ εἰς δεκάδα, τὴν τελευταίαν", "st": "109"}, {"sp": "N", "t": "ἀπολύτρωσιν. ἀφ’ οὗ μοι δοκεῖ καὶ Μωυσῆς μετὰ τὴν χιλιάρχων καὶ ἑκατοντάρχων καὶ πεντηκοντάρχων αἵρεσιν ἐπὶ πᾶσι δεκαδάρχους χειροτονεῖν, ἵν’, εἰ μὴ δύναιτο διὰ τῶν πρεσβυτέρων τάξεων βελτιοῦσθαι ὁ νοῦς, ἀλλά τοι διὰ τῶν ὑστάτων καθαίρηται.", "st": "110"}, {"sp": "N", "t": "πάγκαλον δὲ δόγμα καὶ ὁ τοῦ φιλομαθοῦς παῖς ἔμαθεν, ἡνίκα τὴν θαυμαστὴν ἐκείνην ἐπρέσβευε πρεσβείαν, αὐτομαθεῖ σοφῷ προξενῶν οἰκειοτάτην ἀρετήν, ἐπιμονήν. “δέκα γὰρ καμήλους λαμβάνει,” τὴν δεκάδος, λέγω δὲ παιδείας ὀρθῆς, ἀνάμνησιν, ἀπὸ πολλῶν ἀπείρων μὲν οὖν τοῦ κυρίου μνημῶν.", "st": "111"}, {"sp": "N", "t": "“λαμβάνει δὲ καὶ τῶν ἀγαθῶν ἐκείνου” δῆλον ὡς οὐκ ἄργυρον οὐδὲ χρυσὸν ἤ τινα ἄλλα τῶν ἐν ὕλαις φθαρταῖς — τὴν γὰρ ἀγαθοῦ πρόσρησιν οὐδέποτε τούτοις ἐπεφήμισε Μωυσῆς —, ἀλλὰ τὰ γνήσια, ἃ δὴ ψυχῆς ἐστι μόνα, ἐφοδιάζεται καὶ ἐμπορεύεται, διδασκαλίαν, προκοπήν, σπουδήν, πόθον, ζῆλον, ἐνθουσιασμούς, προφητείας, τοῦ κατορθοῦν ἔρωτα·", "st": "112"}, {"sp": "N", "t": "οἷς ἐμμελετῶν καὶ ἐνασκούμενος, ὅταν ὥσπερ ἐκ πελάγους ἐνορμίζεσθαι λιμένι μέλλῃ, λήψεται δύο μὲν ἐνώτια, ἀνὰ δραχμὴν ὁλκήν, ψέλια δὲ δέκα χρυσῶν ἐπὶ τὰς χεῖρας τῆς προξενουμένης. ὢ θεοπρεποῦς κόσμου, δραχμὴν μίαν εἶναι τὸ ἄκουσμα καὶ μονάδα ἀρραγῆ καὶ ὁλκὸν φύσει — ἀκοὴν γὰρ οὐδενὶ σχολάζειν ἐμπρεπές, ὅτι μὴ λόγῳ ἑνί, ὃς ἂν τὰς τοῦ ἑνὸς ἀρετὰς καὶ μόνου θεοῦ καλῶς διεξέρχηται —, δέκα δὲ χρυσῶν τὰ ἐγχειρήματα· πράξεις γὰρ αἱ κατὰ σοφίαν τελείοις ἀριθμοῖς βεβαιοῦνται, καὶ ἔστιν ἑκάστη τιμιωτέρα χρυσοῦ.", "st": "113"}, {"sp": "N", "t": "τοιαύτη τίς ἐστι καὶ ἡ ἀριστίνδην ἐπικριθεῖσα τῶν ἀρχόντων εἰσφορά, ἣν ἐποιήσαντο, ἡνίκα ἡ ψυχὴ κατασκευασθεῖσα ὑπὸ φιλοσοφίας ἱεροπρεπῶς τὰ ἐγκαίνια ἦγεν αὐτῆς εὐχαριστοῦσα τῷ διδασκάλῳ καὶ ὑφηγητῇ θεῷ. “θυΐσκην γὰρ δέκα χρυσῶν πλήρη θυμιάματος ἀνατίθησιν”, ἵνα τὰς ὑπὸ φρονήσεως καὶ πάσης ἀρετῆς ἀναδιδομένας αὔρας ὁ μόνος ἐπικρίνῃ σοφός.", "st": "114"}, {"sp": "N", "t": "ἐπειδὰν δὲ δόξωσιν εἶναι προσηνεῖς, τὸ ἐφύμνιον ᾄσεται Μωυσῆς λέγων· “ὠσφράνθη κύριος ὀσμὴν εὐωδίας”, τὸ ὀσφρανθῆναι τιθεὶς ἐπὶ τοῦ συναινέσαι· οὐ γὰρ ἀνθρωπόμορφος οὐδὲ μυκτήρων ἤ τινων ἄλλων ὀργανικῶν μερῶν χρεῖος.", "st": "115"}, {"sp": "N", "t": "προϊὼν δὲ καὶ τὸ θεῖον ἐνδιαίτημα, τὴν σκηνήν, “δέκα αὐλαίας” ἐρεῖ· τὸ γὰρ τῆς ὅλης πῆγμα σοφίας ἀριθμὸν τέλειον εἴληχε, δεκάδα· σοφία δὲ αὐλὴ καὶ βασίλειόν ἐστι τοῦ πανηγεμόνος καὶ μόνου βασιλέως αὐτοκράτορος.", "st": "116"}, {"sp": "N", "t": "ὁ μὲν δὴ νοητὸς οἶκος οὗτος, αἰσθητὸς δ’ ὁ κόσμος ἐστίν, ἐπεὶ καὶ τὰς αὐλαίας ἐκ τοιούτων συνύφηνεν, ἃ τῶν τεττάρων στοιχείων σύμβολά ἐστιν· ἐκ γὰρ βύσσου καὶ ὑακίνθου καὶ πορφύρας καὶ κοκκίνου δημιουργοῦνται, τεττάρων, ὡς ἔφην, ἀριθμῶν. σύμβολον δὲ γῆς μὲν ἡ βύσσος — φύεται γὰρ ἐκ ταύτης —, ἀέρος δὲ ὁ ὑάκινθος — μέλας γὰρ οὗτος φύσει —, ὕδατος δὲ ἡ πορφύρα — τὸ γὰρ τῆς βαφῆς αἴτιον ἐκ θαλάττης, ἡ ὁμωνυμοῦσα κόγχη —, πυρὸς δὲ τὸ κόκκινον· ἐμφερέστατον γὰρ φλογί.", "st": "117"}, {"sp": "N", "t": "πάλιν γε μὴν Αἴγυπτον ἀφηνιάσασαν, ἡνίκα τὸν ἀντίθεον ἀπεσέμνυνε νοῦν τὰ παράσημα τῆς βασιλείας ἀναδοῦσα αὐτῷ, τὸν θρόνον, τὸ σκῆπτρον, τὸ διάδημα, δέκα πληγαῖς καὶ τιμωρίαις ὁ τῶν ὅλων ἐπίτροπος καὶ κηδεμὼν νουθετεῖ.", "st": "118"}, {"sp": "N", "t": "τὸν αὐτὸν δὲ τρόπον καὶ Ἀβραὰμ ὑπισχνεῖται τῷ σοφῷ οὔτε πλειόνων οὔτε ἐλαττόνων, ἀλλὰ αὐτὸ μόνον δέκα ἐθνῶν ἀπώλειαν καὶ παντελῆ φθορὰν ἐργάσεσθαι καὶ τὴν τῶν ἀναιρεθέντων χώραν δώσειν τοῖς ἐγγόνοις αὐτοῦ, πανταχοῦ δεκάδι καὶ πρὸς ἔπαινον καὶ πρὸς ψόγον καὶ πρὸς τιμὴν καὶ πρὸς κόλασιν καταχρῆσθαι δικαιῶν.", "st": "119"}, {"sp": "N", "t": "καίτοι τί τούτων μεμνήμεθα; τὴν γὰρ ἱερὰν καὶ θείαν νομοθεσίαν δέκα τοῖς σύμπασι λόγοις Μωυσῆς ἀναγέγραφεν· οὗτοι δέ εἰσι θεσμοί, τῶν κατὰ μέρος ἀπείρων νόμων γενικὰ κεφάλαια, ῥίζαι καὶ ἀρχαὶ καὶ πηγαὶ ἀέναοι διαταγμάτων προστάξεις καὶ ἀπαγορεύσεις περιεχόντων ἐπ’ ὠφελείᾳ τῶν χρωμένων.", "st": "120"}, {"sp": "N", "t": "Εἰκότως οὖν μετὰ δεκαετίαν τῆς εἰς Χαναναίων γῆν ἀφίξεως ἡ πρὸς τὴν Ἄγαρ κοινωνία γίνεται· οὐ γὰρ εὐθὺς λογικοὶ γενόμενοι πλαδώσης ἔτι τῆς διανοίας ὀρεχθῆναι παιδείας τῆς ἐγκυκλίου δυνάμεθα, ἀλλ’ ἐπειδὰν σύνεσιν καὶ ἀγχίνοιαν κραταιωσάμενοι μηκέτι κούφῃ καὶ ἐπιπολαίῳ, ἀλλὰ βεβαίᾳ καὶ παγίᾳ γνώμῃ περὶ ἁπάντων χρώμεθα.", "st": "121"}, {"sp": "N", "t": "διὸ τἀκόλουθον προσυφαίνεται τὸ “εἰσῆλθε πρὸς Ἄγαρ”· ἦν γὰρ ἁρμόττον τῷ μανθάνοντι πρὸς ἐπιστήμην διδάσκαλον φοιτᾶν, ἵνα ἀναδιδαχθῇ τὰ προσήκοντα ἀνθρώπου φύσει παιδεύματα. νυνὶ μὲν ὁ γνώριμος εἰς διδασκάλου βαδίζων εἰσάγεται· προεκτρέχει δὲ πολλάκις ἐξοικίσασα φθόνον ἀφ’ ἑαυτῆς καὶ τοὺς ἔχοντας εὐφυῶς ἐπισπᾶται.", "st": "122"}, {"sp": "N", "t": "τὴν γοῦν ἀρετήν, Λείαν, ἔστιν ἰδεῖν προαπαντῶσαν καὶ λέγουσαν τῷ ἀσκητῇ· “πρὸς μὲ εἰσελεύσῃ σήμερον”, ἡνίκα ἐκεῖνος ἀγρόθεν ἐπανῄει. ποῦ γὰρ ὤφειλεν εἰσελθεῖν ὁ τῶν ἐπιστήμης σπερμάτων καὶ φυτῶν ἐπιμελητής, ὅτι μὴ πρὸς τὴν γεωργηθεῖσαν ἀρετήν;", "st": "123"}, {"sp": "N", "t": "ἔστι δ’ ὅτε καὶ ἀποπειρωμένη τῶν φοιτητῶν, ὡς ἔχουσι προθυμίας καὶ σπουδῆς, οὐχ ὑπαντᾷ μέν, ἐγκαλυψαμένη δὲ τὸ πρόσωπον ὥσπερ Θάμαρ ἐπὶ τριόδου καθέζεται, πόρνης δόξαν παρασχοῦσα τοῖς ὁδῷ βαδίζουσιν, ἵνα οἱ περιέργως ἔχοντες ἀνακαλύψαντες ἀναφήνωσι καὶ καταθεάσωνται τὸ ἄψαυστον καὶ ἀμίαντον καὶ παρθένιον ὄντως αἰδοῦς καὶ σωφροσύνης ἐκπρεπέστατον κάλλος.", "st": "124"}, {"sp": "N", "t": "τίς οὖν ὁ ἐξεταστικὸς καὶ φιλομαθὴς καὶ μηδὲν ἄσκεπτον καὶ ἀδιερεύνητον τῶν ἐγκεκαλυμμένων πραγμάτων παραλιπεῖν ἀξιῶν ἐστιν, ὅτι μὴ ὁ ἀρχιστράτηγος καὶ βασιλεὺς καὶ ταῖς πρὸς θεὸν ὁμολογίαις ἐμμένων τε καὶ χαίρων, ὄνομα Ἰούδας; “ἐξέκλινε” γάρ φησι “πρὸς αὐτὴν τὴν ὁδὸν καὶ εἶπεν· ἔασόν με εἰσελθεῖν πρὸς σέ” — ἀλλ’ οὐκ ἔμελλε παραβιάζεσθαι — καὶ σκοπεῖν, τίς τε ἡ ἐγκεκαλυμμένη δύναμίς ἐστι καὶ ἐπὶ τί παρεσκεύασται.", "st": "125"}, {"sp": "N", "t": "μετὰ τοίνυν τὸ εἰσελθεῖν γέγραπται “καὶ συνέλαβε” καὶ τὸ “τίς” ῥητῶς οὐ μεμήνυται· συλλαμβάνει γὰρ καὶ συναρπάζει ἡ μὲν τέχνη τὸν μανθάνοντα ἐρωτικῶς ἔχειν ἀναπείθουσα ἑαυτῆς, ὁ δὲ μανθάνων τὴν διδάσκουσαν, ὁπότε φιλομαθὴς εἴη.", "st": "126"}, {"sp": "N", "t": "πολλάκις δέ τις τῶν μέσας ἐπιστήμας ὑφηγουμένων γνωρίμου τυχὼν εὐφυοῦς ηὔχησεν ἐπὶ τῇ διδασκαλίᾳ μόνος ὑπολαβὼν τῷ φοιτητῇ γεγονέναι τῆς εὐμαθίας αἴτιος, καὶ μετεωρίσας καὶ φυσήσας ἑαυτὸν ὑψαυχενεῖ καὶ τὰς ὀφρῦς εὖ μάλα ἀνασπάσας τετύφωται καὶ παρὰ τῶν βουλομένων συνδιατρίβειν πάμπολλα αἰτεῖ· οὓς δ’ ἂν αἴσθηται πένητας μέν, διψῶντας δὲ παιδείας, ἀποστρέφεται, ὥσπερ θησαυρόν τινα σοφίας μόνος ἀνευρηκώς.", "st": "127"}, {"sp": "N", "t": "τοῦτ’ ἐστὶ τὸ “ἐν γαστρὶ ἔχειν”, οἰδεῖν καὶ τετυφῶσθαι καὶ ὄγκον πλείονα τοῦ μετρίου περιβεβλῆσθαι, δι’ ὧν καὶ τὴν κυρίαν τῶν μέσων ἐπιστημῶν, ἀρετήν, ἔδοξάν τινες ἀτιμάζειν, ἐπίτιμον οὖσαν ἐξ ἑαυτῆς.", "st": "128"}, {"sp": "N", "t": "ὅσαι μὲν οὖν ψυχαὶ μετὰ φρονήσεως κυοφοροῦσι πραγμάτων τίκτουσιν ὅμως, τὰ συγκεχυμένα διακρίνουσαι καὶ διαστέλλουσαι, καθάπερ ἡ Ῥεβέκκα — λαβοῦσα γὰρ ἐν γαστρὶ τῶν διττῶν διανοίας ἐθνῶν ἐπιστήμην, ἀρετῆς τε καὶ κακίας, εὐτοκίᾳ χρωμένη τὴν ἑκατέρου φύσιν διαστέλλει τε καὶ διακρίνει —· ὅσαι δὲ ἄνευ φρονήσεως, ἢ ἀμβλίσκουσιν ἢ δύσεριν καὶ σοφιστὴν βάλλοντα καὶ τοξεύοντα ἢ βαλλόμενον καὶ τοξευόμενον ἀποκύουσι.", "st": "129"}, {"sp": "N", "t": "καὶ μήποτε εἰκότως· αἱ μὲν γὰρ λαμβάνειν, αἱ δὲ ἔχειν ἐν γαστρὶ οἴονται, παμμεγέθους οὔσης διαφορᾶς. αἱ μὲν γὰρ ἔχειν νομίζουσαι τὴν αἵρεσιν καὶ γένεσιν ἑαυταῖς ἐπιγράφουσαι σεμνομυθοῦσιν, αἱ δὲ λαμβάνειν ἀξιοῦσαι τὸ μὲν μηδὲν οἰκεῖον ἐξ ἑαυτῶν ἔχειν συνομολογοῦσι, τὰ δὲ σπέρματα καὶ τὰς γονὰς ἔξωθεν ἀρδομένας καταλαμβάνουσαι καὶ θαυμάζουσαι τὸν διδόντα κακὸν μέγιστον, φιλαυτίαν, ἀγαθῷ τελείῳ, θεοσεβείᾳ, διωθοῦνται.", "st": "130"}, {"sp": "N", "t": "τοῦτον τὸν τρόπον καὶ τὰ νομοθετικῆς τῆς παρὰ ἀνθρώποις κατεβλήθη σπέρματα· “ἦν γάρ τις” φησίν “ἐκ τῆς φυλῆς Λευί, ὃς ἔλαβε τῶν θυγατέρων τῶν Λευί, καὶ ἔσχεν αὐτήν. καὶ ἐν γαστρὶ ἔλαβε καὶ ἔτεκεν ἄρρεν· ἰδόντες δὲ αὐτὸ ἀστεῖον ὂν ἐσκέπασαν αὐτὸ μῆνας τρεῖς”.", "st": "131"}, {"sp": "N", "t": "οὗτός ἐστι Μωυσῆς, ὁ καθαρώτατος νοῦς, ὁ ἀστεῖος ὄντως, ὁ νομοθετικὴν ὁμοῦ καὶ προφητείαν ἐνθουσιώσῃ καὶ θεοφορήτῳ σοφίᾳ λαβών, ὃς γένος ὢν τῆς Λευιτικῆς φυλῆς καὶ τὰ πρὸς πατρὸς καὶ τὰ πρὸς μητρὸς ἀμφιθαλὴς τῆς ἀληθείας ἔχεται.", "st": "132"}, {"sp": "N", "t": "μέγιστον δὲ ἐπάγγελμα τοῦ γενάρχου τῆς φυλῆς ἐστι ταύτης· θαρρεῖ γὰρ λέγειν, ὅτι αὐτός μοι μόνος ἐστὶ θεὸς τιμητέος, ἄλλο δ’ οὐδὲν τῶν μετ’ αὐτόν, οὐ γῆ, οὐ θάλασσα, οὐ ποταμοί, οὐκ ἀέρος φύσις, οὐ πνευμάτων οὐχ ὡρῶν μεταβολαί, οὐ ζῴων οὐ φυτῶν ἰδέαι, οὐχ ἥλιος, οὐ σελήνη, οὐκ ἀστέρων πλῆθος ἐν τάξεσιν ἐναρμονίοις περιπολούντων, οὐχ ὁ σύμπας οὐρανός τε καὶ κόσμος.", "st": "133"}, {"sp": "N", "t": "μεγάλης καὶ ὑπερφυοῦς ψυχῆς τὸ αὔχημα, γένεσιν ὑπερκύπτειν καὶ τοὺς ὅρους αὐτῆς ὑπερβάλλειν καὶ μόνου τοῦ ἀγενήτου περιέχεσθαι κατὰ τὰς ἱερὰς ὑφηγήσεις, ἐν αἷς διείρηται “ἔχεσθαι αὐτοῦ”. τοιγάρτοι τοῖς ἐχομένοις καὶ ἀδιαστάτως θεραπεύουσιν ἀντιδίδωσι κλῆρον αὑτόν. ἐγγυᾶται δέ μου τὴν ὑπόσχεσιν λόγιον, ἐν ᾧ λέγεται· “κύριος αὐτὸς κλῆρος αὐτοῦ”.", "st": "134"}, {"sp": "N", "t": "οὕτως ἐν γαστρὶ λαμβάνουσαι μᾶλλον ἢ ἔχουσαι αἱ ψυχαὶ τίκτειν πεφύκασι. καθάπερ δ’ οἱ σώματος ὀφθαλμοὶ πολλάκις μὲν ἀμυδρῶς πολλάκις δὲ τηλαυγῶς ὁρῶσι, τὸν αὐτὸν τρόπον καὶ τὸ τῆς ψυχῆς ὄμμα τοτὲ μὲν ὑποσυγκεχυμένας καὶ ἀδήλους τοτὲ δὲ καθαρὰς καὶ τρανὰς δέχεται τὰς ἀπὸ τῶν πραγμάτων ἰδιότητας.", "st": "135"}, {"sp": "N", "t": "ἡ μὲν οὖν ἀσαφὴς καὶ ἀδηλουμένη προσβολὴ ἔοικε τῷ μήπω κατὰ γαστρὸς ἐμβρύῳ διατυπωθέντι, ἡ δὲ ἐναργὴς καὶ τρανὴ μάλιστα τῷ διαπεπλασμένῳ καὶ καθ’ ἕκαστον τῶν ἐντός τε καὶ ἐκτὸς μερῶν τετεχνιτευμένῳ καὶ τὴν ἁρμόττουσαν ἰδέαν ἀπειληφότι.", "st": "136"}, {"sp": "N", "t": "νόμος δὲ ἐπὶ τούτοις ἐγράφη πάνυ καλῶς καὶ συμφερόντως τεθεὶς οὗτος· “ἐὰν μαχομένων ἀνδρῶν δύο πατάξῃ τις γυναῖκα ἐν γαστρὶ ἔχουσαν καὶ ἐξέλθῃ τὸ παιδίον αὐτῆς μὴ ἐξεικονισμένον, ἐπιζήμιον ζημιωθήσεται· καθ’ ὅ τι ἂν ἐπιβάλῃ ὁ ἀνὴρ τῆς γυναικός, δώσει μετὰ ἀξιώματος· ἐὰν δὲ ἐξεικονισμένον ᾖ, δώσει ψυχὴν ἀντὶ ψυχῆς”. οὐ γὰρ ἦν ὅμοιον, τέλειόν τε καὶ ἀτελὲς διανοίας ἔργον διαφθεῖραι, οὐδὲ εἰκαζόμενον καὶ καταλαμβανόμενον, οὐδὲ ἐλπιζόμενον καὶ ἤδη ὑπάρχον.", "st": "137"}, {"sp": "N", "t": "διὰ τοῦτο ὅπου μὲν ἐπιτίμιον ἄδηλον ἐπ’ ἀδήλῳ πράγματι, ὅπου δὲ ὡρισμένον ἐπὶ τελείῳ νομοθετεῖται, τελείῳ δὲ οὐχὶ τῷ πρὸς ἀρετήν, ἀλλὰ τῷ κατά τινα τέχνην τῶν ἀνεπιλήπτων γενομένῳ· κυοφορεῖ γὰρ αὐτὸ οὐχ ἡ λαβοῦσα, ἀλλ’ ἡ ἐν γαστρὶ ἔχουσα, οἴησιν πρὸ ἀτυφίας ἐπαγγελλομένη. καὶ γὰρ ἀμήχανον ἀμβλίσκειν τὴν ἐν γαστρὶ λαβοῦσαν, ἐπεὶ τὸ φυτὸν ὑπὸ τοῦ σπείραντος ἐμπρεπὲς τελεσφορεῖσθαι· τὴν δὲ ἔχουσαν οὐκ ἀνοίκειον, ἅτε νόσῳ χωρὶς ἰατροῦ κατεσχημένην.", "st": "138"}, {"sp": "N", "t": "Μὴ νομίσῃς δὲ τὴν Ἄγαρ λέγεσθαι ἑαυτὴν ὁρᾶν ἐν γαστρὶ ἔχουσαν διὰ τοῦ “ἰδοῦσα ὅτι ἐν γαστρὶ ἔχει”, ἀλλὰ τὴν κυρίαν αὐτῆς Σάρραν. καὶ γὰρ ὕστερον αὕτη περὶ ἑαυτῆς φησιν· “ἰδοῦσα ὅτι ἐν γαστρὶ ἔχει, ἠτιμάσθην ἐνώπιον αὐτῆς”.", "st": "139"}, {"sp": "N", "t": "διὰ τί; ὅτι αἱ μέσαι τέχναι, καὶ εἰ τὰ καθ’ αὑτάς, ὧν εἰσιν ἐγκύμονες, ὁρῶσιν, ἀλλά τοι πάντως ἀμυδρῶς ὁρῶσιν, ἀλλ’ ἐπιστῆμαι τηλαυγῶς καὶ σφόδρα ἐναργῶς καταλαμβάνουσιν· ἐπιστήμη γὰρ πλέον ἐστὶ τέχνης, τὸ βέβαιον καὶ ἀμετάπτωτον ὑπὸ λόγου προσειληφυῖα.", "st": "140"}, {"sp": "N", "t": "τέχνης μὲν γὰρ ὅρος οὗτος· σύστημα ἐκ καταλήψεων συγγεγυμνασμένων πρός τι τέλος εὔχρηστον, τοῦ εὐχρήστου διὰ τὰς κακοτεχνίας ὑγιῶς προστιθεμένου· ἐπιστήμης δέ· κατάληψις ἀσφαλὴς καὶ βέβαιος, ἀμετάπτωτος ὑπὸ λόγου.", "st": "141"}, {"sp": "N", "t": "μουσικὴν μὲν οὖν καὶ γραμματικὴν καὶ τὰς συγγενεῖς καλοῦμεν τέχνας — καὶ γὰρ οἱ ἀποτελούμενοι δι’ αὐτῶν τεχνῖται λέγονται μουσικοί τε καὶ γραμματικοί —, φιλοσοφίαν δὲ καὶ τὰς ἄλλας ἀρετὰς ἐπιστήμας καὶ τοὺς ἔχοντας αὐτὰς ἐπιστήμονας· φρόνιμοι γάρ εἰσι καὶ σώφρονες καὶ φιλόσοφοι, ὧν οὐδὲ εἷς ἐν τοῖς τῆς διαπεπονημένης ἐπιστήμης σφάλλεται δόγμασι, καθάπερ οἱ προειρημένοι ἐν τοῖς τῶν μέσων τεχνῶν θεωρήμασιν.", "st": "142"}, {"sp": "N", "t": "ὥσπερ γὰρ ὀφθαλμοὶ μὲν ὁρῶσιν, ὁ δὲ νοῦς δι’ ὀφθαλμῶν τηλαυγέστερον, καὶ ἀκούει μὲν ὦτα, ὁ δὲ νοῦς δι’ ὤτων ἄμεινον, καὶ ὀσφραίνονται μὲν οἱ μυκτῆρες, ἡ δὲ ψυχὴ διὰ ῥινῶν ἐναργέστερον, καὶ αἱ ἄλλαι αἰσθήσεις τῶν καθ’ αὑτὰς ἀντιλαμβάνονται, καθαρώτερον δὲ καὶ εἱλικρινέστερον ἡ διάνοια — κυρίως γὰρ εἰπεῖν ἥδ’ ἐστὶν ὀφθαλμὸς μὲν ὀφθαλμῶν, ἀκοὴ δὲ ἀκοῆς καὶ ἑκάστης τῶν αἰσθήσεων αἴσθησις εἱλικρινεστέρα, χρωμένη μὲν ἐκείναις ὡς ἐν δικαστηρίῳ ὑπηρέτισι, δικάζουσα δ’ αὐτὴ τὰς φύσεις τῶν ὑποκειμένων, ὡς τοῖς μὲν συναινεῖν, τὰ δὲ ἀποστρέφεσθαι —, οὕτως αἱ μὲν λεγόμεναι μέσαι τέχναι ταῖς κατὰ τὸ σῶμα δυνάμεσιν ἐοικυῖαι τοῖς θεωρήμασιν ἐντυγχάνουσι κατά τινας ἁπλᾶς ἐπιβολάς, ἀκριβέστερον δὲ ἐπιστῆμαι καὶ σὺν ἐξετάσει περιττῇ.", "st": "143"}, {"sp": "N", "t": "ὃ γὰρ νοῦς πρὸς αἴσθησιν, τοῦτ’ ἐπιστήμη πρὸς τέχνην ἐστί· καθάπερ γὰρ αἴσθησίς τις αἰσθήσεων, ὡς ἐλέχθη πρότερον, ἐστὶν ἡ ψυχή * * * ἐκείνων μὲν οὖν ἑκάστη μικρὰ ἄττα τῶν ἐν τῇ φύσει παρεσπάσατο, περὶ ἃ πονεῖται καὶ πραγματεύεται, γραμμὰς μὲν γεωμετρία, φθόγγους δὲ μουσική, φιλοσοφία δὲ πᾶσαν τὴν τῶν ὄντων φύσιν· ὕλη γάρ ἐστιν αὐτῆς ὅδε ὁ κόσμος καὶ πᾶσα ἡ τῶν ὄντων ὁρατή τε καὶ ἀόρατος οὐσία.", "st": "144"}, {"sp": "N", "t": "τί οὖν θαυμαστόν, εἰ ἡ τὰ ὅλα καθορῶσα θεᾶται καὶ τὰ μέρη, καὶ ἄμεινον ἐκείνων, ἅτε ὀφθαλμοῖς μείζοσι καὶ ὀξυδερκεστέροις ἐνομματωθεῖσα; εἰκότως οὖν ἡ κυρία φιλοσοφία τὴν μέσην παιδείαν, τὴν θεραπαινίδα αὐτῆς, ἐγκύμονα θεάσεται μᾶλλον ἢ ἑαυτὴν ἐκείνη.", "st": "145"}, {"sp": "N", "t": "καίτοι γ’ οὐδὲ τοῦτό τις ἀγνοεῖ, ὅτι πάσαις ταῖς κατὰ μέρος τὰς ἀρχὰς καὶ τὰ σπέρματα, ἐξ ὧν ἀναβλαστεῖν ἔδοξε τὰ θεωρήματα, φιλοσοφία δεδώρηται. ἰσόπλευρα γὰρ καὶ σκαληνὰ κύκλους τε καὶ πολυγώνια καὶ τὰ ἄλλα σχήματα γεωμετρία προσεξεῦρε, σημείου δὲ καὶ γραμμῆς καὶ ἐπιφανείας καὶ στερεοῦ φύσιν, ἃ δὴ ῥίζαι καὶ θεμέλιοι τῶν λεχθέντων εἰσίν, οὐκέτι γεωμετρία.", "st": "146"}, {"sp": "N", "t": "πόθεν γὰρ αὐτῇ λέγειν ὁριζομένῃ, ὅτι σημεῖον μέν ἐστιν οὗ μέρος οὐδέν, γραμμὴ δὲ μῆκος ἀπλατές, ἐπιφάνεια δὲ ὃ μῆκος καὶ πλάτος μόνον ἔχει, στερεὸν δὲ ὃ τὰς τρεῖς ἔχει διαστάσεις, μῆκος, πλάτος, βάθος; ταῦτα γὰρ ἀνάκειται φιλοσοφίᾳ καὶ ἡ περὶ ὅρων πραγματεία πᾶσα τῷ φιλοσόφῳ.", "st": "147"}, {"sp": "N", "t": "τό γε μὴν γράφειν καὶ ἀναγινώσκειν γραμματικῆς τῆς ἀτελεστέρας ἐπάγγελμα, ἣν παρατρέποντές τινες γραμματιστικὴν καλοῦσι, τῆς δὲ τελειοτέρας ἀνάπτυξις τῶν παρὰ ποιηταῖς τε καὶ συγγραφεῦσιν. ἐπειδὰν οὖν περὶ τῶν τοῦ λόγου διεξέρχωνται μερῶν, τότε οὐ τὰ φιλοσοφίας εὑρήματα παρασπῶνταί τε καὶ παρεργολαβοῦσι;", "st": "148"}, {"sp": "N", "t": "ταύτης γὰρ ἴδιον ἐξετάζειν, τί σύνδεσμος, τί ὄνομα, τί ῥῆμα, τί κοινὸν ὄνομα, τί ἴδιον, τί ἐλλιπὲς ἐν λόγῳ, τί πλῆρες, τί ἀποφαντόν, τί ἐρώτημα, τί πύσμα, τί περιεκτικόν, τί εὐκτικόν, τί ἀρατικόν· τὰς γὰρ περὶ αὐτοτελῶν καὶ ἀξιωμάτων καὶ κατηγορημάτων πραγματείας ἥδ’ ἐστὶν ἡ συνθεῖσα.", "st": "149"}, {"sp": "N", "t": "ἡμίφωνον δὲ ἢ φωνῆεν ἢ παντελῶς ἄφωνον στοιχεῖον ἰδεῖν, καὶ πῶς ἕκαστον τούτων εἴωθε λέγεσθαι, καὶ πᾶσα ἡ περὶ φωνῆς καὶ στοιχείων καὶ τῶν τοῦ λόγου μερῶν ἰδέα οὐ φιλοσοφίᾳ πεπόνηται καὶ κατήνυσται; βραχείας δ’ ὥσπερ ἀπὸ χειμάρρου σπάσαντες λιβάδας καὶ βραχυτέραις ταῖς ἑαυτῶν ψυχαῖς ἐναποθλίψαντες τὸ κλαπὲν οἱ φῶρες οὐκ ἐρυθριῶσι προφέροντες ὡς ἴδιον.", "st": "150"}, {"sp": "N", "t": "Οὗ χάριν φρυαττόμενοι τῆς κυρίας, ᾗ τὸ κῦρος ὄντως καὶ ἡ τῶν θεωρουμένων ἀνάκειται βεβαίωσις, ἀλογοῦσι. συναισθομένη δὲ αὕτη τῆς ὀλιγωρίας τούτων ἐλέγξει καὶ μετὰ παρρησίας φήσει· ἀδικοῦμαι καὶ παρασπονδοῦμαι τό γε ἐφ’ ὑμῖν ὁμολογίας παραβαίνουσιν.", "st": "151"}, {"sp": "N", "t": "ἀφ’ οὗ γὰρ ἐνεκολπίσασθε τὰ προπαιδεύματα, τῆς ἐμῆς θεραπαινίδος τὰ ἔγγονα, τὴν μὲν ὡς γαμετὴν ἐξετιμήσατε, ἐμὲ δὲ οὕτως ἀπεστράφητε, ὡς μηδὲ πώποτε ἐς ταὐτὸν ἐλθόντες. ἀλλ’ ἴσως ἐγὼ μὲν ταῦτα περὶ ὑμῶν ὑπείληφα, ἐκ τῆς φανερᾶς πρὸς τὴν οἰκέτιν ὁμιλίας τὴν ἄδηλον πρὸς ἐμὲ αὐτὴν ἀλλοτρίωσιν τεκμαιρομένη· εἰ δ’ ὑμεῖς ἐναντίως ἢ ὡς ὑπείληφα διάκεισθε, γνῶναι μὲν ἀμήχανον ἑτέρῳ, ῥᾴδιον δὲ μόνῳ θεῷ.", "st": "152"}, {"sp": "N", "t": "διόπερ οἰκείως ἐρεῖ· “κρίναι ὁ θεὸς ἀνὰ μέσον ἐμοῦ καὶ σοῦ”, οὐ προκατεγνωκυῖα ὡς ἠδικηκότος, ἀλλ’ ἐνδοιάζουσα ὡς τάχ’ ἂν ἴσως καὶ κατορθοῦντος· ὅπερ ἀψευδῶς οὐκ εἰς μακρὰν ἀναφαίνεται δι’ ὧν ἀπολογούμενος καὶ τὸν ἐνδοιασμὸν αὐτῆς ἐξιώμενός φησιν· “ἰδοὺ ἡ παιδίσκη ἐν ταῖς χερσί σου, χρῶ αὐτῇ, ὡς ἄν σοι ἀρεστὸν ᾖ”.", "st": "153"}, {"sp": "N", "t": "καὶ γὰρ ὁ παιδίσκην εἰπὼν ἀμφότερα ὁμολογεῖ, τό τε δούλην καὶ τὸ νηπίαν εἶναι — τὸ γὰρ τῆς παιδίσκης ὄνομα ἑκατέρῳ τούτων ἐφαρμόζει —, συνομολογεῖ δὲ πάντως εὐθὺς καὶ τἀναντία, τῇ μὲν νηπίᾳ τὴν τελείαν, τῇ δὲ δούλῃ τὴν κυρίαν, μονονοὺ βοῶν ἄντικρυς, ὅτι τὴν μὲν ἐγκύκλιον παιδείαν καὶ ὡς νεωτέραν καὶ ὡς θεραπαινίδα ἀσπάζομαι, τὴν δὲ ἐπιστήμην καὶ φρόνησιν ὡς τελείαν καὶ δέσποιναν ἐκτετίμηκα.", "st": "154"}, {"sp": "N", "t": "τὸ δὲ “ἐν ταῖς χερσί σου” δηλοῖ μὲν τὸ ὑποχείριός ἐστί σοι. σημαίνει δὲ καὶ τοιοῦτον ἕτερον· τὰ μὲν τῆς δούλης εἰς χεῖρας ἀφικνεῖται σώματος — σωματικῶν γὰρ ὀργάνων καὶ δυνάμεων τὰ ἐγκύκλια χρεῖα —, τὰ δὲ τῆς κυρίας εἰς ψυχὴν ἔρχεται· λογισμοῖς γὰρ τὰ κατά τε φρόνησιν καὶ ἐπιστήμην ἀνατίθεται.", "st": "155"}, {"sp": "N", "t": "ὥσθ’ ὅσῳ δυνατώτερον καὶ δραστικώτερον καὶ τοῖς ὅλοις κρεῖττον διάνοια χειρός ἐστι, τοσούτῳ τῆς ἐγκυκλίου μουσικῆς ἐπιστήμην καὶ φρόνησιν θαυμασιωτέραν εἶναι νενόμικα καὶ διαφερόντως ἐκτετίμηκα. λαβοῦσα οὖν, ὦ καὶ ὑπάρχουσα καὶ πρὸς ἐμοῦ νομιζομένη κυρία, τὴν ἐμὴν ἅπασαν παιδείαν ὡς θεραπαινίδι χρῶ, “ὡς εὐάρεστόν σοι.”", "st": "156"}, {"sp": "N", "t": "τὸ δὲ σοὶ εὐάρεστον οὐκ ἀγνοῶ ὅτι πάντως ἐστὶν ἀγαθόν, εἰ καὶ μὴ προσηνές, καὶ ὠφέλιμον, εἰ καὶ μακρὰν τοῦ ἡδέος ἀφέστηκεν. ἀγαθὸν δὲ καὶ ὠφέλιμον τοῖς ἐλέγχου δεομένοις νουθεσία, ὃ ἑτέρῳ ὀνόματι κάκωσιν ὁ ἱερὸς μηνύει λόγος.", "st": "157"}, {"sp": "N", "t": "Διόπερ ἐπιφέρει· “καὶ ἐκάκωσεν αὐτὴν”, ἴσον τῷ ἐνουθέτησε καὶ ἐσωφρόνισε. λυσιτελὲς γὰρ σφόδρα τοῖς ἐν ἀδείᾳ καὶ ἐκεχειρίᾳ, καθάπερ ἵπποις ἀφηνιασταῖς, ὀξὺ κέντρον, ἐπεὶ μάστιγι μόλις καὶ ἀγωγῇ δαμασθῆναι καὶ τιθασευθῆναι δύνανται.", "st": "158"}, {"sp": "N", "t": "ἢ τὰ προκείμενα ἆθλα οὐχ ὁρᾷς τοῖς ἀνεπιπλήκτοις; λιπῶσιν, εὐρύνονται, πιαίνονται, λαμπρὸν πνέουσιν· εἶτα αἴρονται τὰ ἀσεβείας, οἱ πανάθλιοι καὶ βαρυδαίμονες, οἰκτρὰ βραβεῖα, ἐπ’ ἀθεότητι κηρυττόμενοι καὶ στεφανούμενοι. διὰ γὰρ τὴν λείως ῥέουσαν εὐτυχίαν ὑπέλαβον ἑαυτοὺς εἶναι τοὺς ὑπαργύρους καὶ ὑποχρύσους θεούς, νομίσματος κεκιβδηλευμένου τὸν τρόπον, τοῦ ἀληθινοῦ καὶ ὄντως ὄντος ἐκλαθόμενοι.", "st": "159"}, {"sp": "N", "t": "μαρτυρεῖ δὲ καὶ Μωυσῆς ἐν οἷς φησιν· “ἐλιπάνθη, ἐπαχύνθη, ἐπλατύνθη καὶ ἐγκατέλιπε θεὸν τὸν ποιήσαντα αὐτόν”· ὥστε εἰ ἡ ἐπὶ πλέον ἄνεσις τὸ μέγιστον κακόν, ἀσέβειαν, ὠδίνει, τοὐναντίον ἡ μετὰ νόμου κάκωσις ἀγαθὸν τέλειον ἀποτίκτει, τὴν ἀοίδιμον νουθεσίαν.", "st": "160"}, {"sp": "N", "t": "ἐνθένδε ὁρμηθεὶς καὶ τῆς πρώτης ἑορτῆς τὸ σύμβολον “ἄρτον κακώσεως” εἶπε, τὰ ἄζυμα. καίτοι τίς οὐκ οἶδεν, ὅτι ἑορταὶ καὶ θαλίαι περιποιοῦσιν ἱλαρὰς εὐφροσύνας καὶ εὐθυμίας, οὐ κακώσεις;", "st": "161"}, {"sp": "N", "t": "ἀλλὰ δῆλον, ὡς ὀνόματι κατακέχρηται πόνου, τοῦ σωφρονιστοῦ. τὰ γὰρ πλεῖστα καὶ μέγιστα τῶν ἀγαθῶν ἀσκητικαῖς ἀθλήσεσι καὶ ἡβῶσι πόνοις εἴωθε περιγίνεσθαι· ψυχῆς δὲ ἑορτὴ ζῆλος ὁ τῶν ἀρίστων καὶ τελεσφορούμενος πόνος. οὗ χάριν διείρηται καὶ “ἐπὶ πικρίδων τὰ ἄζυμα ἐσθίειν” οὐχ ὡς προσεψήματος, ἀλλ’ ἐπειδὴ τὸ μὴ οἰδεῖν καὶ ἀναζεῖν ταῖς ἐπιθυμίαις, ἐστάλθαι δὲ καὶ συνῆχθαι πρὸς ἀηδίας οἱ πολλοὶ τίθενται, πικρὸν ἡγούμενοι τὸ ἀπομαθεῖν τὸ πάθος, ὅπερ ἐστὶν", "st": "162"}, {"sp": "N", "t": "εὐφροσύνη καὶ ἑορτὴ διανοίᾳ φιλάθλῳ. ταύτης ἕνεκά μοι δοκεῖ τῆς αἰτίας ἐν χωρίῳ, ὃ κέκληται πικρία, τὰ νόμιμα ἀναδιδαχθῆναι· ἡδὺ μὲν γὰρ τὸ ἀδικεῖν, ἐπίπονον δὲ τὸ δικαιοπραγεῖν· τοῦτο δέ ἐστιν ὁ ἀψευδέστατος νόμος. ἐξελθόντες, γάρ φησιν, ἐκ τῶν Αἰγυπτιακῶν παθῶν “ἦλθον εἰς Μερρά, καὶ οὐκ ἠδύναντο πιεῖν ὕδωρ ἐκ Μερρῶν· πικρὸν γὰρ ἦν. διὰ τοῦτο ἐπωνομάσθη τὸ ὄνομα τοῦ τόπου ἐκείνου πικρία. καὶ διεγόγγυζεν ὁ λαὸς κατὰ Μωυσῆ λέγοντες· τί πιόμεθα; ἐβόησε δὲ Μωυσῆς πρὸς κύριον, καὶ ἔδειξεν αὐτῷ κύριος ξύλον, καὶ ἐνέβαλεν αὐτὸ εἰς τὸ ὕδωρ, καὶ ἐγλυκάνθη τὸ ὕδωρ. ἐκεῖ ἔθετο αὐτῷ δικαιώματα καὶ κρίσεις, κἀκεῖ αὐτὸν ἐπείραζεν”.", "st": "163"}, {"sp": "N", "t": "ἡ γὰρ ἄδηλος ἀπόπειρα καὶ δοκιμασία τῆς ψυχῆς ἐστιν ἐν τῷ πονεῖν καὶ πικραίνεσθαι· ὅπῃ γὰρ ταλαντεύσει, χαλεπὸν διαγνῶναι. οἱ μὲν γὰρ προκαμόντες ἀνέπεσον, βαρὺν ἀντίπαλον ἡγησάμενοι τὸν πόνον, καὶ τὰς χεῖρας ὑπ’ ἀσθενείας ὥσπερ ἀπειρηκότες ἀθληταὶ καθῆκαν, παλινδρομεῖν εἰς Αἴγυπτον ἐπὶ τὴν ἀπόλαυσιν τοῦ πάθους ἐγνωκότες.", "st": "164"}, {"sp": "N", "t": "οἱ δὲ τὰ φοβερὰ καὶ δεινὰ τῆς ἐρήμης πάνυ τλητικῶς καὶ ἐρρωμένως ἀναδεχόμενοι τὸν ἀγῶνα τοῦ βίου διήθλησαν ἀδιάφθορον καὶ ἀήττητον φυλάξαντες καὶ τῶν τῆς φύσεως ἀναγκαίων κατεξαναστάντες, ὡς πεῖναν, δίψος [ῥῖγος], κρύος, θάλπος, ὅσα τοὺς ἄλλους εἴωθε δουλοῦσθαι, κατὰ πολλὴν ἰσχύος περιουσίαν ὑπάγεσθαι.", "st": "165"}, {"sp": "N", "t": "αἴτιον δὲ ἐγένετο οὐ ψιλὸς ὁ πόνος, ἀλλὰ σὺν τῷ γλυκανθῆναι· λέγει γάρ· “ἐγλυκάνθη τὸ ὕδωρ,” γλυκὺς δὲ καὶ ἡδὺς πόνος ἑτέρῳ ὀνόματι φιλοπονία καλεῖται. τὸ γὰρ ἐν πόνῳ γλυκὺ ἔρως ἐστὶ καὶ πόθος καὶ ζῆλος καὶ φιλία τοῦ καλοῦ.", "st": "166"}, {"sp": "N", "t": "μηδεὶς οὖν τὴν τοιαύτην κάκωσιν ἀποστρεφέσθω, μηδ’ “ἄρτον κακώσεως” νομισάτω ποτὲ λέγεσθαι τὴν ἑορτῆς καὶ εὐφροσύνης τράπεζαν ἐπὶ βλάβῃ μᾶλλον ἢ ὠφελείᾳ· τρέφεται γὰρ τοῖς παιδείας δόγμασιν ἡ νουθετουμένη ψυχή.", "st": "167"}, {"sp": "N", "t": "τὸ ἄζυμον πέμμα τοῦτο οὕτως ἐστὶν ἱερόν, ὥστε χρησμοῖς προστέτακται δώδεκα ἄρτους ἀζύμους ταῖς φυλαῖς ἰσαρίθμους προτιθέναι ἐπὶ τῆς ἐν τοῖς ἀδύτοις χρυσῆς τραπέζης, καὶ καλοῦνται προθέσεως.", "st": "168"}, {"sp": "N", "t": "καὶ νόμῳ δὲ ἀπείρηται πᾶσαν ζύμην καὶ πᾶν μέλι προσφέρειν τῷ βωμῷ· χαλεπὸν γὰρ ἢ τὰς γλυκύτητας τῶν κατὰ τὸ σῶμα ἡδονῶν ἢ τὰς τῆς ψυχῆς ἀραιὰς καὶ χαύνους ἐπάρσεις καθιεροῦν ὡς ἅγια, τὰ φύσει βέβηλα καὶ ἀνίερα ἐξ αὑτῶν.", "st": "169"}, {"sp": "N", "t": "ἆρ’ οὖν οὐκ εἰκότως ἐπισεμνυνόμενος ὁ προφήτης λόγος, ὄνομα Μωυσῆς, ἐρεῖ· “μνησθήσῃ πᾶσαν τὴν ὁδὸν ἣν ἤγαγέ σε κύριος ὁ θεὸς ἐν ἐρήμῳ, ὅπως ἂν κακώσῃ σε καὶ ἐκπειράσῃ σε καὶ διαγνωσθῇ τὰ ἐν καρδίᾳ σου, εἰ φυλάξεις ἐντολὰς αὐτοῦ ἢ οὔ· καὶ ἐκάκωσέ σε καὶ ἐλιμαγχόνησέ σε καὶ ἐψώμισέ σε τὸ μάννα, ὃ οὐκ ᾔδεισαν οἱ πατέρες σου, ἵνα ἀναγγείλῃ σοι, ὅτι οὐκ ἐπ’ ἄρτῳ μόνῳ ζήσεται ὁ ἄνθρωπος, ἀλλ’ ἐν παντὶ ῥήματι ἐκπορευομένῳ διὰ στόματος θεοῦ”;", "st": "170"}, {"sp": "N", "t": "τίς οὖν οὕτως ἀνόσιός ἐστιν, ὡς ὑπολαβεῖν κακωτὴν τὸν θεὸν καὶ λιμόν, οἴκτιστον ὄλεθρον, ἐπάγοντα τοῖς ἄνευ τροφῆς ζῆν μὴ δυναμένοις; ἀγαθὸς γὰρ καὶ ἀγαθῶν αἴτιος, εὐεργέτης, σωτήρ, τροφεύς, πλουτοφόρος, μεγαλόδωρος, κακίαν ὅρων ἱερῶν ἀπεληλακώς· οὕτω γὰρ τὰ γῆς ἄχθη, τόν τε Ἀδὰμ καὶ Κάιν, ἐφυγάδευσεν ἐκ τοῦ παραδείσου. μὴ παραγώμεθα οὖν ταῖς φωναῖς,", "st": "171"}, {"sp": "N", "t": "ἀλλὰ τὰ δι’ ὑπονοιῶν σημαινόμενα σκοπῶμεν καὶ λέγωμεν, ὅτι τὸ μὲν “ἐκάκωσε” ἴσον ἐστὶ τῷ ἐπαίδευσε καὶ ἐνουθέτησε καὶ ἐσωφρόνισε, τὸ δὲ “λιμῷ παρέβαλεν” οὐ σιτίων καὶ ποτῶν εἰργάσατο ἔνδειαν, ἀλλ’ ἡδονῶν καὶ ἐπιθυμιῶν φόβων τε καὶ λύπης καὶ ἀδικημάτων καὶ συνόλως ἁπάντων ὅσα ἢ κακιῶν ἐστιν ἢ παθῶν ἔργα.", "st": "172"}, {"sp": "N", "t": "μαρτυρεῖ δὲ τὸ ἐπιλεγόμενον ἑξῆς· “ἐψώμισέ σε τὸ μάννα.” ἆρά γε τὸν τὴν ἄπονον καὶ ἀταλαίπωρον τροφὴν δίχα σπουδῆς τῶν ἀνθρώπων οὐκ ἐκ γῆς, ὡς ἔθος, ἀναδοθεῖσαν, ἀπ’ οὐρανοῦ δέ, τεράστιον ἔργον, ἐπ’ εὐεργεσίᾳ τῶν χρησομένων παρασχόμενον ἄξιον λέγειν λιμοῦ καὶ κακώσεως ἢ τοὐναντίον εὐθηνίας καὶ εὐετηρίας ἀδείας τε καὶ εὐνομίας αἴτιον;", "st": "173"}, {"sp": "N", "t": "ἀλλ’ οἱ πολλοὶ καὶ ἀγελαῖοι νομίζουσι τοὺς λόγοις θείοις τρεφομένους ἀθλίως καὶ ταλαιπώρως ζῆν — ἄγευστοι γάρ εἰσι τοῦ παντρόφου γεύματος σοφίας —, οἱ δ’ ἐν ταῖς εὐπαθείαις καὶ εὐφροσύναις λελήθασι διάγοντες.", "st": "174"}, {"sp": "N", "t": "οὕτω τοίνυν ἡ ποιὰ κάκωσις ὠφέλιμόν ἐστιν, ὥστε καὶ τὸ ταπεινότατον αὐτῆς, ἡ δουλεία, μέγα ἀγαθὸν νενόμισται. καὶ ταύτην ηὔξατό τις ἐν ταῖς ἱεραῖς ἀναγραφαῖς πατὴρ υἱῷ, τῷ ἄφρονι Ἠσαῦ ὁ ἄριστος Ἰσαάκ.", "st": "175"}, {"sp": "N", "t": "εἶπε γάρ που· “ἐπὶ μαχαίρᾳ σου ζήσεις, καὶ τῷ ἀδελφῷ σου δουλεύσεις”, λυσιτελέστατον κρίνων τῷ πόλεμον ἀντ’ εἰρήνης αἱρουμένῳ καὶ ὥσπερ ἐν μάχαις ὁπλοφοροῦντι διὰ τὴν ἐν τῇ ψυχῇ στάσιν καὶ ταραχὴν ὑπηκόῳ γενέσθαι καὶ δουλεῦσαι καὶ ἐπιτάγμασιν, ἅττ’ ἂν ὁ σωφροσύνης ἐραστὴς ἐπικελεύσῃ, πᾶσι πειθαρχεῖν.", "st": "176"}, {"sp": "N", "t": "ἐνθένδε μοι δοκεῖ τις τῶν φοιτητῶν Μωυσέως, ὄνομα εἰρηνικός, ὃς πατρίῳ γλώττῃ Σαλομὼν καλεῖται, φάναι· “παιδείας θεοῦ, υἱέ, μὴ ὀλιγώρει, καὶ μὴ ἐκλύου ὑπ’ αὐτοῦ ἐλεγχόμενος· ὃν γὰρ ἀγαπᾷ κύριος ἐλέγχει, μαστιγοῖ δὲ πάντα υἱὸν ὃν παραδέχεται”. οὕτως ἄρα ἡ ἐπίπληξις καὶ νουθεσία καλὸν νενόμισται, ὥστε δι’ αὐτῆς ἡ πρὸς θεὸν ὁμολογία συγγένεια γίνεται. τί γὰρ οἰκειότερον υἱῷ πατρὸς ἢ υἱοῦ πατρί;", "st": "177"}, {"sp": "N", "t": "ἀλλ’ ἵνα μὴ λόγον ἐκ λόγου συνείροντες μηκύνειν δοκῶμεν, ἐναργεστάτην δίχα τῶν εἰρημένων πίστιν παρεξόμεθα τοῦ τὴν ποιὰν κάκωσιν ἀρετῆς ἔργον εἶναι· νόμος γάρ ἐστι τοιοῦτος· “πᾶσαν χήραν καὶ ὀρφανὸν οὐ κακώσετε· ἐὰν δὲ κακίᾳ κακώσητε αὐτούς”. τί λέγει; ἆρ’ ὑπό τινος ἔστιν ἄλλου κακοῦσθαι; εἰ γὰρ κακίας ἔργα μόνης αἱ κακώσεις, περιττὸν τὸ ὁμολογούμενον γράφειν, ὃ καὶ δίχα προσθήκης ἀνομολογηθήσεται.", "st": "178"}, {"sp": "N", "t": "φήσει δὲ πάντως· οἶδα καὶ ὑπὸ ἀρετῆς ἐλεγχόμενον καὶ ὑπὸ φρονήσεως παιδευόμενον. διόπερ οὐ πᾶσαν κάκωσιν ἐν αἰτίᾳ τίθεμαι, ἀλλὰ τὴν μὲν δικαιοσύνης καὶ νομοθετικῆς ἔργον οὖσαν — ἐπιπλήξει γὰρ σωφρονίζει — μάλιστα θαυμάζω, τὴν δὲ ἀφροσύνης καὶ κακίας, βλαβερὰν ὑπάρχουσαν, ἀποστρέφομαι καὶ κακίζω δεόντως.", "st": "179"}, {"sp": "N", "t": "ὅταν οὖν τὴν Ἄγαρ κακουμένην ὑπὸ Σάρρας ἀκούσῃς, μηδὲν τῶν ἐν ταῖς γυναικείαις ζηλοτυπίαις εἰωθότων γίνεσθαι ὑπονοήσῃς· οὐ γὰρ περὶ γυναικῶν ἐστιν ὁ λόγος, ἀλλὰ διανοιῶν, τῆς μὲν γυμναζομένης ἐν τοῖς προπαιδεύμασι, τῆς δὲ τοὺς ἀρετῆς ἄθλους διαθλούσης.", "st": "180"}], []);})();
